import React, { useState, useEffect, useContext, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import SubscriptionSection from '../components/SubscriptionSection';
// Only the loading spinner is still Chakra; everything else uses
// native circuit-design widgets.
import { Spinner } from '@chakra-ui/react';
import fetchData from '../utils/Util';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import PhoneInput, { getCountries } from 'react-phone-number-input';
import flags from 'react-phone-number-input/flags';
import AddressForm from '../components/AddressForm';
import { formatPhoneNumberIntl } from 'react-phone-number-input';
import ChangePassword from '../components/ChangePassword';
import { handleSaveAddress, handleDeleteAddress, fetchAddresses } from '../utils/AddressUtils';

const MyAccount = ({ showChangePasswordTab }) => {
  const { t } = useTranslation();
  const [activeTab, setActiveTab] = useState(0);
  const [successMessage, setSuccessMessage] = useState(null);
  const [country, setCountry] = useState('US'); // Define country state
  const [formattedMobile, setFormattedMobile] = useState('');
  const [phoneCountry, setPhoneCountry] = useState('US'); // Define phone country state
  const [formattedPhoneNumber, setFormattedPhoneNumber] = useState(''); // Define formatted phone number state
  const [isValidEmail, setIsValidEmail] = useState(true);
  const [namePrefixes, setNamePrefixes] = useState([]);
  const [isAddingNewAddress, setIsAddingNewAddress] = useState(false);
  const [addressTabIndex, setAddressTabIndex] = useState(0);
  const [isChangingDefaultAddress, setIsChangingDefaultAddress] = useState(false);
  const [consentToEmails, setConsentToEmails] = useState(false);
  const [receivePrintedMaterials, setReceivePrintedMaterials] = useState(false);
  const config = useContext(ConfigContext);

  const [boUserData, setBoUserData] = useState(null);
  const [addresses, setAddresses] = useState([]);
  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    name_prefix: '',
    email: '',
    phone: '',
    mobile: '',
    company: '',
    client_website: '',
    birthdate: '',
    // subscribe_to_newsletter: '',
    // interested_in: '',
    website_language: '',
    client_billing_instruction: '',
    shipping_instructions_client: '',
    block_emails: true,
    professional_references: '',
    subscription_type: '',
    cancellation_date: null,
    receive_printed_materials: false,
  });
  const [error, setError] = useState('');
  const [isLoading, setIsLoading] = useState(true);

  const handlePhoneChange = useCallback((value, data, field) => {
    const countryCode = data?.countryCode || '';
    const phoneNumber = value ? `${countryCode}${value}` : '';
    const formattedNumber = value ? formatPhoneNumberIntl(phoneNumber) : '';
  
    if (field === 'phone') {
      setFormattedPhoneNumber(formattedNumber);
      setPhoneCountry(data?.countryCode || phoneCountry);
    } else if (field === 'mobile') {
      setFormattedMobile(formattedNumber);
      setCountry(data?.countryCode || country);
    }
  
    setFormData((prevFormData) => ({
      ...prevFormData,
      [field]: value,
    }));
  }, [country, phoneCountry]);

  const hasSavedAddresses = () => {
    return !isLoading && addresses.some(address => address.id);
  };

  // Fet bo user.
  useEffect(() => {
    /**
     * Get datatable-clients from the backoffice API.
     */
    const fetchBoUserData = async () => {
      try {
        if (!config.userData || !config.userData.uuid) {
          // Wait until data is fully loaded.
          return;
        }
        if (!config.userData.bo_access_token) {
          setError(t('myAccount.connectionFailed'));
          return;
        }
        const response = await fetchData(
          `${config.siteData.backoffice_url_lang}/api/v1.0/datatable-clients?filter[uuid][value]=${config.userData.uuid}`,
          {
            mockData: 'api-me',
            headers: { 'access-token': config.userData.bo_access_token },
          }
        );
        if (!response.ok) {
          throw new Error(response.title || t('myAccount.networkError'));
        }
        const result = await response.json();
        const data = result.data[0];
        setBoUserData(data);
        setFormData({
          first_name: data.first_name || '',
          last_name: data.last_name || '',
          name_prefix: data.name_prefix?.id || '',
          email: data.email || '',
          phone: data.phone || '',
          mobile: data.mobile || '',
          company: data.company || '',
          client_website: data.client_website || '',
          birthdate: data.birthdate ? new Date(data.birthdate).getTime() : null,
          // subscribe_to_newsletter: data.subscribe_to_newsletter || '',
          // interested_in: data.interested_in || '',
          website_language: data.website_language || '',
          client_billing_instruction: data.client_billing_instruction || '',
          shipping_instructions_client: data.shipping_instructions_client || '',
          block_emails: data.block_emails !== undefined ? data.block_emails : true,
          professional_references: data.professional_references || '',
          subscription_type: data.subscription_type || '',
          cancellation_date: data.cancellation_date || null,
          receive_printed_materials: data.receive_printed_materials || false,
        });

        setConsentToEmails(data.block_emails !== undefined ? !data.block_emails : false);
        setReceivePrintedMaterials(data.receive_printed_materials || false);

      } catch (error) {
        setError(error.message);
      }
    };

    const fetchDataAsync = async () => {
      await fetchBoUserData();
   };

    fetchDataAsync().catch((error) => {
      setError(error.message);
      setIsLoading(false);
    });
  }, [config, t]);

  
  const handleConsentChange = (e) => {
    const isConsenting = e.target.checked;
    setConsentToEmails(isConsenting);

    setFormData({
      ...formData,
      block_emails: !isConsenting,
    });
  };

  const handlePrintedMaterialsChange = (e) => {
    const isChecked = e.target.checked;
    setReceivePrintedMaterials(isChecked);

    setFormData({
      ...formData,
      receive_printed_materials: isChecked,
    });
  };

  useEffect(() => {
    const detectCountry = () => {
      const browserLanguage = navigator.language || navigator.userLanguage;
      const [languageCode, countryCode] = browserLanguage.split('-');
      
      if (countryCode) {
        return countryCode.toUpperCase();
      } else {
        const countries = getCountries();
        const matchingCountry = countries.find(country => country.toLowerCase() === languageCode.toLowerCase());
        return matchingCountry || 'US';
      }
    };
  
    const detectedCountry = detectCountry();
    setCountry(detectedCountry);
    setPhoneCountry(detectedCountry);
  }, []);

  // Fetch prefix.
  useEffect(() => {

    const fetchNamePrefixes = async () => {
      if (!config || !config.userData || !config.userData.bo_access_token) return;
      try {
        const response = await fetchData(
          `${config.siteData.backoffice_url_lang}/api/v1.0/name_prefixes`,
          {
            mockData: 'api-name-prefixes',
            headers: { 'access-token': config.userData.bo_access_token },
          }
        );
        if (!response.ok) {
          throw new Error(response.title || 'Network response was not ok for name prefixes');
        }
        const data = await response.json();
        setNamePrefixes(data.data);
      }
      catch (error) {
        setError(error.message);
      }
    };

   fetchNamePrefixes().catch((error) => {
      setError(error.message);
      setIsLoading(false);
    });
  }, [config, namePrefixes.length, config.userData?.bo_access_token, config.siteData]);

  // Fetch address.
  useEffect(() => {

    const fetchUserAddresses = async () => {
      try {
        if (!boUserData || !config.userData?.bo_access_token) return;
        
        // Use common fetch addresses utility
        const addressesData = await fetchAddresses({ 
          config, 
          clientId: boUserData.id 
        });
        
        setAddresses(addressesData);
      } catch (error) {
        setError(error.message);
      }
    };

    fetchUserAddresses().catch((error) => {
      setError(error.message);
      setIsLoading(false);
    });

    setIsLoading(false);

  }, [config, boUserData, config.userData?.bo_access_token]);

  useEffect(() => {
    if (isChangingDefaultAddress) {
      return; 
    }
    if (isAddingNewAddress || addresses.length === 0) {
      setActiveTab(2); // Set to address tab if adding new address or no addresses
    } else if (showChangePasswordTab) {
      setActiveTab(1); // Set to change password tab if requested
    } else {
      setActiveTab(0); // Set to first tab (personal info) by default
    }
    // isChangingDefaultAddress is intentionally omitted from the deps:
    // re-running when it clears would yank the user off the Addresses tab
    // right after they change their default address.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [addresses, showChangePasswordTab, isAddingNewAddress]);

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });

    // Check email validity
    if (e.target.name === 'email') {
      validateEmail(e.target.value); // Add this line
    }
  };

  // Add function to validate email
  const validateEmail = (email) => {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    setIsValidEmail(emailRegex.test(email));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSuccessMessage('');
    setError('');

    if (!isValidEmail) {
      setError('Please enter a valid email address.');
      return;
    }

    let websiteUrl = formData.client_website;
    if (websiteUrl && websiteUrl.trim() !== '') {
      if (!websiteUrl.match(/^https?:\/\//i)) {
        websiteUrl = `https://${websiteUrl}`;
      }
    }

    // Update phone/ date to formatted values.
    const updatedFormData = {
      ...formData,
      mobile: formattedMobile ? formattedMobile : formData.mobile,
      phone: formattedPhoneNumber ? formattedPhoneNumber : formData.phone,
      client_website: websiteUrl,
    };

    // Prepare data for API submission (convert birthdate to seconds for backoffice)
    const apiData = {
      ...updatedFormData,
      birthdate: formData.birthdate ? Math.floor(formData.birthdate / 1000) : null,
    };

    setFormData(updatedFormData);

    fetch(`${config.siteData.backoffice_url_lang}/api/datatable-clients/${boUserData.id}`, {
      method: 'PATCH',
      headers: {
        'Content-Type': 'application/json',
        'access-token': config.userData.bo_access_token,
      },
      body: JSON.stringify(apiData),
    })
      .then((response) => {

        if (!response.ok) {
          response.json().then((res) => setError(res.title || 'Network error when updating account'));
        }
        return response.json();
      })
      .then((data) => {
        setSuccessMessage('Your account details have been updated');
        setError('');
      })
      .catch((error) => {
        setError(error.message);
      });
  };
  const handleDateChange = (date) => {
    setFormData({
      ...formData,
      birthdate: date ? date.getTime() : null, // Convert to timestamp
    });
  };

  const handleAddNewAddress = () => {
    const newAddress = {
      default_address: false,
      address_types: [],
      address: {
        name_prefix: '',
        first_name: '',
        care_of: '',
        last_name: '',
        organisation_name: '',
        thoroughfare: '',
        premise: '',
        locality: '',
        administrative_area: '',
        postal_code: '',
        country: '',
      },
    };
    setAddresses([...addresses, newAddress]);
    setIsAddingNewAddress(true);
    setActiveTab(2); 
    setAddressTabIndex(addresses.length);
  };

  const handleDeleteAddressLocal = async (index) => {
    try {
      const addressId = addresses[index].id;
      
      // Use common delete address utility
      await handleDeleteAddress({ config, addressId });

      const updatedAddresses = addresses.filter((_, idx) => idx !== index);
      setAddresses(updatedAddresses);
      setSuccessMessage('Address deleted successfully');
    } catch (error) {
      setError('An error occurred while deleting the address. Please try again.');
    }
  };

  const handleSaveAddressLocal = async (index, data) => {
    try {
      const isUpdate = !!addresses[index].id; // Check if there's an address id
      const addressId = isUpdate ? addresses[index].id : null;

      // Use common save address utility
      const savedAddress = await handleSaveAddress({
        config,
        addressFormData: data,
        addressId,
        clientId: boUserData.id
      });

      const updatedAddresses = [...addresses];
      updatedAddresses[index] = savedAddress;

      // If the saved address is set as default, update all other addresses to not be default
      if (data.defaultAddress) {
        const updatedAddressesWithDefaultReset = updatedAddresses.map((address, idx) => {
          if (idx !== index) {
            return { ...address, default_address: false };
          }
          return address;
        });
        setAddresses(updatedAddressesWithDefaultReset);
      } else {
        setAddresses(updatedAddresses);
      }

      setSuccessMessage('Address saved successfully');
    } catch (error) {
      setError(error.message);
    }
  };

  const handleAddressChange = (index, data) => {
    const currentAddressTabIndex = addressTabIndex;   

    if ('default_address' in data) {
      setIsChangingDefaultAddress(true);
    }

    const updatedAddresses = [...addresses];
    updatedAddresses[index] = { ...updatedAddresses[index], ...data };
    setAddresses(updatedAddresses);
    if ('default_address' in data && data.default_address) {
      const addressesWithUpdatedDefaults = updatedAddresses.map((address, idx) => {
        if (idx !== index) {
          return { ...address, default_address: false };
        }
        return address;
      });
      setAddresses(addressesWithUpdatedDefaults);
    }
    setAddressTabIndex(currentAddressTabIndex);

    if ('default_address' in data) {
      setTimeout(() => setIsChangingDefaultAddress(false), 0);
    }
  };

  if (isLoading || !config.userData || !config.siteData) {
    return (
      <div className="account account--loading">
        <Spinner color="blue.500" size="xl" thickness="4px" />
      </div>
    );
  }

  if (config.success === false) {
    return (
      <div className="account">
        <div className="cream-note cream-note--error" role="alert">
          Cannot access site settings.
        </div>
      </div>
    );
  }

  const tabs = [
    { key: 'personal', label: t('myAccount.tabs.personalInfo') },
    { key: 'password', label: t('myAccount.tabs.changePassword') },
    { key: 'addresses', label: t('myAccount.tabs.addresses') },
  ];

  return (
    <div className="account">
      {!isLoading && !hasSavedAddresses() && (
        <div className="cream-note cream-note--warning" role="alert">
          {t('myAccount.noAddressesMessage')}
        </div>
      )}

      <section className="rc-card account-card">
        <header className="card-head">
          <h2 className="page-title">{t('myAccount.title')}</h2>
        </header>

        <nav className="acct-tabs" role="tablist" aria-label={t('myAccount.title')}>
          {tabs.map((tab, idx) => (
            <button
              key={tab.key}
              type="button"
              role="tab"
              aria-selected={activeTab === idx}
              className={`acct-tab${activeTab === idx ? ' is-active' : ''}`}
              onClick={() => setActiveTab(idx)}
            >
              {tab.label}
            </button>
          ))}
        </nav>

        <div className="card-body">
          {activeTab === 0 && (
            <form onSubmit={handleSubmit} className="acct-form">
              <div className="field">
                <label htmlFor="name_prefix" className="field-label">
                  {t('myAccount.namePrefix')}
                </label>
                <select
                  id="name_prefix"
                  name="name_prefix"
                  value={formData.name_prefix}
                  onChange={handleChange}
                  className="field-select"
                >
                  <option value="">{t('myAccount.selectTitle')}</option>
                  {namePrefixes.map((prefix) => (
                    <option key={prefix.id} value={prefix.id}>
                      {prefix.label}
                    </option>
                  ))}
                </select>
              </div>

              <div className="field">
                <label htmlFor="first_name" className="field-label">
                  {t('myAccount.firstName')}<span className="req">*</span>
                </label>
                <input
                  id="first_name"
                  type="text"
                  name="first_name"
                  value={formData.first_name}
                  onChange={handleChange}
                  placeholder={t('myAccount.enterFirstName')}
                  required
                  className="field-input"
                />
              </div>

              <div className="field">
                <label htmlFor="last_name" className="field-label">
                  {t('myAccount.lastName')}<span className="req">*</span>
                </label>
                <input
                  id="last_name"
                  type="text"
                  name="last_name"
                  value={formData.last_name}
                  onChange={handleChange}
                  placeholder={t('myAccount.enterLastName')}
                  required
                  className="field-input"
                />
              </div>

              <div className="field">
                <label htmlFor="email" className="field-label">
                  {t('myAccount.email')}<span className="req">*</span>
                </label>
                <input
                  id="email"
                  type="email"
                  name="email"
                  value={formData.email}
                  onChange={handleChange}
                  placeholder={t('myAccount.enterEmail')}
                  required
                  className="field-input"
                />
              </div>

              <div className="field">
                <label className="field-label">{t('myAccount.mobileNumber')}</label>
                {/* TODO(circuit): replace react-phone-number-input with a native
                    phone field once a pattern is documented. Restyled in
                    styles.scss via the .PhoneInput class names. */}
                <PhoneInput
                  className="phone-input-dropdown"
                  country={country}
                  value={formData.mobile}
                  onChange={(value, data) => handlePhoneChange(value, data, 'mobile')}
                  placeholder={t('myAccount.enterMobileNumber')}
                  onCountryChange={(countryCode) => setCountry(countryCode)}
                  flags={flags}
                  defaultCountry={country}
                />
                {formattedMobile && (
                  <p className="field-format">
                    <span>{t('myAccount.standardInternationalFormat', 'Standard International Format')}</span>
                    <span className="field-format__value">{formattedMobile}</span>
                  </p>
                )}
              </div>

              <div className="field">
                <label className="field-label">{t('myAccount.phoneNumber')}</label>
                <PhoneInput
                  className="phone-input-dropdown"
                  country={phoneCountry}
                  value={formData.phone}
                  onChange={(value, data) => handlePhoneChange(value, data, 'phone')}
                  placeholder={t('myAccount.enterPhoneNumber')}
                  onCountryChange={(countryCode) => setPhoneCountry(countryCode)}
                  flags={flags}
                  defaultCountry={phoneCountry}
                />
                {formattedPhoneNumber && (
                  <p className="field-format">
                    <span>{t('myAccount.standardInternationalFormat')}</span>
                    <span className="field-format__value">{formattedPhoneNumber}</span>
                  </p>
                )}
                <p className="field-help">{t('myAccount.phoneNumberInstructions')}</p>
              </div>

              <div className="field">
                <label htmlFor="company" className="field-label">{t('myAccount.company')}</label>
                <input
                  id="company"
                  type="text"
                  name="company"
                  value={formData.company}
                  onChange={handleChange}
                  placeholder={t('myAccount.enterCompany')}
                  className="field-input"
                />
              </div>

              <div className="field">
                <label htmlFor="client_website" className="field-label">{t('myAccount.website')}</label>
                <input
                  id="client_website"
                  type="text"
                  name="client_website"
                  value={formData.client_website}
                  onChange={handleChange}
                  placeholder={t('myAccount.enterWebsite')}
                  className="field-input"
                />
              </div>

              <div className="field">
                <label className="field-label">{t('myAccount.birthDate')}</label>
                {/* TODO(circuit): replace react-datepicker with a native
                    date field once a pattern is documented. Restyled via
                    .react-datepicker-wrapper input in styles.scss. */}
                <DatePicker
                  selected={formData.birthdate ? new Date(formData.birthdate) : null}
                  onChange={handleDateChange}
                  dateFormat="dd/MM/yyyy"
                  showMonthDropdown
                  showYearDropdown
                  dropdownMode="select"
                  placeholderText={t('myAccount.selectBirthDate')}
                />
              </div>

              {config.siteData?.languages?.length > 1 && (
                <div className="field">
                  <label htmlFor="website_language" className="field-label">
                    {t('myAccount.language')}
                  </label>
                  <select
                    id="website_language"
                    name="website_language"
                    value={formData.website_language}
                    onChange={handleChange}
                    className="field-select"
                  >
                    <option value="">{t('myAccount.selectLanguage')}</option>
                    {config.siteData.languages.map((lang) => (
                      <option key={lang} value={lang}>
                        {t(`myAccount.languages.${lang}`)}
                      </option>
                    ))}
                  </select>
                </div>
              )}

              <div className="field">
                <label htmlFor="professional_references" className="field-label">
                  {t('myAccount.professionalReferences')}
                </label>
                <textarea
                  id="professional_references"
                  name="professional_references"
                  value={formData.professional_references}
                  onChange={handleChange}
                  placeholder={t('myAccount.enterProfessionalReferences')}
                  className="field-textarea"
                  rows={4}
                />
                <p className="field-help">{t('myAccount.professionalReferencesInstructions')}</p>
              </div>

              <div className="field">
                <label htmlFor="client_billing_instruction" className="field-label">
                  {t('myAccount.billingInstructions')}
                </label>
                <textarea
                  id="client_billing_instruction"
                  name="client_billing_instruction"
                  value={formData.client_billing_instruction}
                  onChange={handleChange}
                  placeholder={t('myAccount.enterBillingInstructions')}
                  className="field-textarea"
                />
              </div>

              <div className="field">
                <label htmlFor="shipping_instructions_client" className="field-label">
                  {t('myAccount.shippingInstructions')}
                </label>
                <textarea
                  id="shipping_instructions_client"
                  name="shipping_instructions_client"
                  value={formData.shipping_instructions_client}
                  onChange={handleChange}
                  placeholder={t('myAccount.enterShippingInstructions')}
                  className="field-textarea"
                />
              </div>

              {/* Magazine Subscription Section (Chakra-based child component;
                  out of scope for this pass — inherits .circuit-user-ui tokens.) */}
              <SubscriptionSection boUserData={boUserData} t={t} />

              <label className="checkbox-row">
                <input
                  type="checkbox"
                  name="consent_to_emails"
                  checked={consentToEmails}
                  onChange={handleConsentChange}
                />
                <span className="checkbox-label">{t('myAccount.optInCommunications')}</span>
              </label>
              <p className="field-help field-help--checkbox">
                {t('myAccount.optInCommunicationsHelp')}
              </p>

              <label className="checkbox-row">
                <input
                  type="checkbox"
                  name="receive_printed_materials"
                  checked={receivePrintedMaterials}
                  onChange={handlePrintedMaterialsChange}
                />
                <span className="checkbox-label">{t('myAccount.receivePrintedMaterials')}</span>
              </label>
              <p className="field-help field-help--checkbox">
                {t('myAccount.receivePrintedMaterialsHelp')}
              </p>

              <p
                className="required-note"
                dangerouslySetInnerHTML={{
                  __html: t('register.requiredFields', { asterisk: '<span class="req">*</span>' }),
                }}
              />

              <div className="card-actions">
                <button type="submit" className="btn-primary-action">
                  {t('myAccount.updateAccount')}
                </button>
              </div>
            </form>
          )}

          {activeTab === 1 && <ChangePassword />}

          {activeTab === 2 && (() => {
            const visibleAddresses = addresses.filter((a) => a.address);
            const safeIndex = Math.min(addressTabIndex, Math.max(visibleAddresses.length - 1, 0));
            const active = visibleAddresses[safeIndex];
            return (
              <div className="address-tab">
                <div style={{ marginBottom: 'var(--space-5)' }}>
                  <button
                    type="button"
                    className="btn-primary-action"
                    onClick={handleAddNewAddress}
                  >
                    {t('myAccount.addNewAddress')}
                  </button>
                </div>

                {visibleAddresses.length === 0 && (
                  <p className="address-empty">
                    {t('addressForm.noAddresses', 'No addresses yet.')}
                  </p>
                )}

                {visibleAddresses.length > 0 && (
                  <>
                    <nav className="acct-subtabs" role="tablist" aria-label={t('myAccount.tabs.addresses')}>
                      {visibleAddresses.map((a, index) => (
                        <button
                          key={index}
                          type="button"
                          role="tab"
                          aria-selected={safeIndex === index}
                          className={`acct-subtab${safeIndex === index ? ' is-active' : ''}`}
                          onClick={() => setAddressTabIndex(index)}
                        >
                          {t('addressForm.addressN', { num: index + 1, defaultValue: `Address ${index + 1}` })}
                        </button>
                      ))}
                    </nav>

                    {active && (
                      <AddressForm
                        key={safeIndex}
                        address={active}
                        onSave={(data) => handleSaveAddressLocal(safeIndex, data)}
                        onDelete={() => handleDeleteAddressLocal(safeIndex)}
                        namePrefixes={namePrefixes}
                        isDefault={active.default_address}
                        onDefaultChange={(value) => handleAddressChange(safeIndex, { default_address: value })}
                        defaultCountry={country}
                        isFirstAddress={addresses.length === 0 || !addresses.some((addr) => addr.id)}
                      />
                    )}
                  </>
                )}
              </div>
            );
          })()}
        </div>
      </section>

      {successMessage && (
        <div className="cream-note cream-note--success" role="status">
          {successMessage}
        </div>
      )}
      {error && (
        <div className="cream-note cream-note--error" role="alert">
          <strong>{t('myAccount.error')}</strong>{error}
        </div>
      )}
    </div>
  );
};

export default MyAccount;
