import React, { useState, useEffect, useContext } from 'react';
import { useTranslation } from 'react-i18next';
import BillingPage from './BillingPage';
import PaymentMethods from './PaymentMethods';
import { ConfigContext } from '../config/Config';
import { fetchPaymentMethods, transformPaymentMethodForComponent } from '../utils/PaymentUtils';

const BillingContainer = () => {
  const { t } = useTranslation();
  const config = useContext(ConfigContext);
  const [activeTab, setActiveTab] = useState(0);
  const [savedCards, setSavedCards] = useState([]);
  const [isLoadingPaymentMethods, setIsLoadingPaymentMethods] = useState(false);

  // Serverless site configs use both spellings of this flag — accept either.
  const paymentGateway = config.siteConfig?.paymentGateway ?? config.siteConfig?.paymentGetaway;
  const hidePaymentMethods = paymentGateway === 'phone';

  // Deep-linking via URL hash.
  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash;
      if (hash === '#payment-methods' && !hidePaymentMethods) {
        setActiveTab(1);
      } else if (hash === '' || hash === '#billing') {
        setActiveTab(0);
      }
    };

    handleHashChange();
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, [hidePaymentMethods]);

  const fetchUserPaymentMethods = async () => {
    try {
      setIsLoadingPaymentMethods(true);
      if (!config.userData || !config.userData.uuid || !config.userData.bo_access_token) {
        return;
      }

      const paymentMethods = await fetchPaymentMethods({ config });
      const transformedCards = paymentMethods.map(transformPaymentMethodForComponent);
      setSavedCards(transformedCards);
    } catch (err) {
      console.error('Error fetching payment methods:', err);
      setSavedCards([]);
    } finally {
      setIsLoadingPaymentMethods(false);
    }
  };

  useEffect(() => {
    if (!hidePaymentMethods && config.userData && config.userData.uuid && config.userData.bo_access_token) {
      fetchUserPaymentMethods();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config.userData, config.siteData, hidePaymentMethods]);

  const handleTabChange = (index) => {
    setActiveTab(index);
    if (index === 0) {
      window.history.replaceState(null, null, '/billing');
    } else if (index === 1) {
      window.history.replaceState(null, null, '/billing#payment-methods');
    }
  };

  const tabs = [
    { key: 'billing', label: t('billing.header') || 'Billing' },
  ];
  if (!hidePaymentMethods) {
    tabs.push({ key: 'payment', label: t('payment.methods') || 'Payment Methods' });
  }

  return (
    <div className="my-billing-page">
      <section className="rc-card account-card my-billing">
        <header className="card-head">
          <h2 className="page-title">{t('userBlock.Billing') || 'Billing'}</h2>
        </header>

        <nav className="acct-tabs" role="tablist" aria-label="Billing">
          {tabs.map((tab, idx) => (
            <button
              key={tab.key}
              type="button"
              role="tab"
              aria-selected={activeTab === idx}
              className={`acct-tab${activeTab === idx ? ' is-active' : ''}`}
              onClick={() => handleTabChange(idx)}
            >
              {tab.label}
            </button>
          ))}
        </nav>

        <div className="card-body">
          {activeTab === 0 && (
            <BillingPage
              savedCards={savedCards}
              isLoadingPaymentMethods={isLoadingPaymentMethods}
            />
          )}
          {activeTab === 1 && !hidePaymentMethods && (
            <PaymentMethods
              savedCards={savedCards}
              setSavedCards={setSavedCards}
              onPaymentMethodsChange={fetchUserPaymentMethods}
            />
          )}
        </div>
      </section>
    </div>
  );
};

export default BillingContainer;
