import React, { createContext, useContext, useCallback, useEffect, useRef } from 'react';
import i18n from '../config/i18n';
import { ConfigContext } from '../config/Config';
import pusherService from './PusherService';

export const DataCacheContext = createContext(null);

// Normalized current language, used to namespace caches that hold localized data.
const getLang = () => (i18n.language || 'en').toLowerCase();

/**
 * Build a localStorage-backed cache wrapper with a TTL.
 * All operations are best-effort — quota errors / disabled storage are swallowed.
 *
 * Options:
 *   perLanguage: when true, keys are namespaced by the current i18n language
 *     (`prefix + lang + ':' + key`) so a German response never satisfies an
 *     English read. `remove(key)` strips the entry across all languages.
 */
const makeLsCache = (prefix, ttlMs, { perLanguage = false } = {}) => {
  const fullKey = (key) => (perLanguage ? `${prefix}${getLang()}:${key}` : `${prefix}${key}`);

  return {
    read(key) {
      try {
        const lsKey = fullKey(key);
        const raw = localStorage.getItem(lsKey);
        if (!raw) return null;
        const entry = JSON.parse(raw);
        if (!entry || !entry.ts || Date.now() - entry.ts > ttlMs) {
          localStorage.removeItem(lsKey);
          return null;
        }
        return entry.data;
      } catch {
        return null;
      }
    },
    write(key, data) {
      try {
        localStorage.setItem(fullKey(key), JSON.stringify({ data, ts: Date.now() }));
      } catch {
        // Quota exceeded or storage disabled — ignore.
      }
    },
    remove(key) {
      try {
        if (!perLanguage) {
          localStorage.removeItem(fullKey(key));
          return;
        }
        // Strip the entry across every language namespace: scan for
        // `${prefix}<lang>:${key}` and drop each match.
        const suffix = `:${key}`;
        const toRemove = [];
        for (let i = 0; i < localStorage.length; i++) {
          const k = localStorage.key(i);
          if (k && k.startsWith(prefix) && k.endsWith(suffix)) toRemove.push(k);
        }
        toRemove.forEach((k) => localStorage.removeItem(k));
      } catch {
        // ignore
      }
    },
    clearAll() {
      try {
        const keys = [];
        for (let i = 0; i < localStorage.length; i++) {
          const k = localStorage.key(i);
          if (k && k.startsWith(prefix)) keys.push(k);
        }
        keys.forEach(k => localStorage.removeItem(k));
      } catch {
        // ignore
      }
    },
  };
};

// Per-language caches: hold localized payloads (titles, labels, descriptions).
// `itemsJsonNidLs` is intentionally NOT per-language — it's a nid -> uuid pointer
// that never changes with locale.
// v2: items-json gained sale_session_timestamp[_end] (add-to-calendar) — the
// namespace bump ignores cached v1 payloads that lack the fields.
const itemsJsonLs = makeLsCache('dc:itemsJson:v2:', 60 * 60 * 1000, { perLanguage: true });
const itemsJsonNidLs = makeLsCache('dc:itemsJsonNid:', 60 * 60 * 1000);
const saleSearchLs = makeLsCache('dc:saleSearch:', 60 * 60 * 1000, { perLanguage: true });
const catalogsLs = makeLsCache('dc:catalogs:', 60 * 60 * 1000, { perLanguage: true });
const salesPublicLs = makeLsCache('dc:salesPublic:', 60 * 60 * 1000, { perLanguage: true });
const saleBsLs = makeLsCache('dc:saleBs:', 60 * 60 * 1000, { perLanguage: true });

// One-time cleanup: older app versions wrote items-json under both nid and uuid
// keys. We now only store under uuid; drop any leftover numeric-keyed entries.
const purgeLegacyItemsJsonNidKeys = () => {
  try {
    const prefix = 'dc:itemsJson:';
    const toRemove = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && k.startsWith(prefix) && /^\d+$/.test(k.slice(prefix.length))) {
        toRemove.push(k);
      }
    }
    toRemove.forEach(k => localStorage.removeItem(k));
  } catch {
    // ignore
  }
};

/**
 * DataCacheProvider
 *
 * Provides a shared cache for sale and item data to prevent duplicate API calls
 * when multiple components request the same data.
 */
export const DataCacheProvider = ({ children }) => {
  const config = useContext(ConfigContext);

  // One-shot: purge legacy nid-keyed `dc:itemsJson:*` entries written by older
  // app versions that double-stored items under both nid and uuid.
  useEffect(() => {
    purgeLegacyItemsJsonNidKeys();
  }, []);

  // Cache storage
  const salesCache = useRef({});
  const itemsCache = useRef({});
  const bidderIdsCache = useRef({});
  const itemsJsonCache = useRef({});
  const saleSearchCache = useRef({});
  const saleInfoCache = useRef({});
  const biddingStatusCache = useRef({});
  const catalogsCache = useRef({});
  const salesPublicCache = useRef({});

  // When the user changes language, drop every in-memory cache that holds
  // localized payloads so subsequent reads re-fetch (and re-cache under the
  // new language namespace in localStorage). bidderIds / biddingStatus are
  // user-state, not localized, so they survive.
  useEffect(() => {
    const clearLocalizedMemCaches = () => {
      salesCache.current = {};
      itemsCache.current = {};
      itemsJsonCache.current = {};
      saleSearchCache.current = {};
      saleInfoCache.current = {};
      catalogsCache.current = {};
      salesPublicCache.current = {};
    };
    i18n.on('languageChanged', clearLocalizedMemCaches);
    return () => {
      i18n.off('languageChanged', clearLocalizedMemCaches);
    };
  }, []);

  // Pending requests to prevent duplicate calls
  const pendingSalesRequests = useRef({});
  const pendingItemsRequests = useRef({});
  const pendingBidderIdsRequests = useRef({});
  const pendingItemsJsonRequests = useRef({});
  const pendingSaleSearchRequests = useRef({});
  const pendingSaleInfoRequests = useRef({});
  const pendingBiddingStatusRequests = useRef({});
  const pendingItemsByIdsRequests = useRef({});
  const pendingCatalogsRequests = useRef({});
  const pendingSalesPublicRequests = useRef({});

  // Track individual UUIDs that are part of pending multiple item requests
  // Maps itemUuid -> Promise that resolves to the individual item
  const pendingMultipleItemUuids = useRef({});

  /**
   * Fetch sale data with caching
   */
  const fetchSale = useCallback(async (saleUuid) => {
    if (!config.backendUrl) {
      throw new Error('fetchSale - Missing required configuration (backendUrl)');
    }
    if (!saleUuid) {
      throw new Error('fetchSale - Missing required configuration (saleUuid)');
    }

    // Return cached data if available (memory or localStorage)
    if (salesCache.current[saleUuid]) {
      return salesCache.current[saleUuid];
    }
    const persisted = saleBsLs.read(saleUuid);
    if (persisted) {
      salesCache.current[saleUuid] = persisted;
      return persisted;
    }

    // Wait for pending request if exists
    if (pendingSalesRequests.current[saleUuid]) {
      return pendingSalesRequests.current[saleUuid];
    }

    // Create new request
    const requestPromise = (async () => {
      try {
        const saleParams = new URLSearchParams({
          'filter[uuid]': saleUuid,
          'fields': 'uuid,currency,label,mail_auction_type',
        });

        const response = await fetch(
          `${config.backendUrl}/api/sales?${saleParams.toString()}`,
          config.accessToken ? { headers: { 'access-token': config.accessToken } } : undefined
        );

        if (!response.ok) {
          throw new Error('Failed to fetch sale data');
        }

        const data = await response.json();
        const sale = data.data?.[0] || null;

        // Cache the result (memory + localStorage)
        salesCache.current[saleUuid] = sale;
        if (sale) saleBsLs.write(saleUuid, sale);

        // Clear pending request
        delete pendingSalesRequests.current[saleUuid];

        return sale;
      } catch (error) {
        // Clear pending request on error
        delete pendingSalesRequests.current[saleUuid];
        throw error;
      }
    })();

    // Store pending request
    pendingSalesRequests.current[saleUuid] = requestPromise;

    return requestPromise;
  }, [config.backendUrl, config.accessToken]);

  /**
   * Fetch item data with caching
   *
   * @param {string|string[]} itemUuid - Single UUID string or array of UUID strings
   * @param {string} saleUuid - Sale UUID (optional when multiple itemUuids are provided)
   * @returns {Promise<Object|Object[]>} - Single item object or array of items
   *
   * Caching strategy:
   * - Items from single queries (with saleUuid): cached as `${saleUuid}:${itemUuid}`
   * - Items from multiple queries (no saleUuid): cached as `${itemUuid}`
   * - Single requests check if UUID is part of a pending multiple request
   */
  const fetchItem = useCallback(async (itemUuid, saleUuid, { reset = false } = {}) => {
    if (!config.backendUrl) {
      throw new Error('fetchItem - Missing required configuration (backendUrl)');
    }
    if (!itemUuid) {
      throw new Error('fetchItem - Missing required configuration (itemUuid)');
    }

    const isMultiple = Array.isArray(itemUuid);

    // ==================== SINGLE UUID MODE ====================
    if (!isMultiple) {
      if (!saleUuid) {
        throw new Error('fetchItem - Missing required configuration (saleUuid)');
      }

      const cacheKey = `${saleUuid}:${itemUuid}`;
      const fallbackCacheKey = `${itemUuid}`;

      if (!reset) {
        // Check primary cache (with saleUuid)
        if (itemsCache.current[cacheKey]) {
          return itemsCache.current[cacheKey];
        }

        // Check fallback cache (from multiple queries without saleUuid)
        if (itemsCache.current[fallbackCacheKey]) {
          return itemsCache.current[fallbackCacheKey];
        }

        // Check if this UUID is part of a pending multiple request
        if (pendingMultipleItemUuids.current[itemUuid]) {
          return pendingMultipleItemUuids.current[itemUuid];
        }

        // Check if there's a pending single request with same cache key
        if (pendingItemsRequests.current[cacheKey]) {
          return pendingItemsRequests.current[cacheKey];
        }
      }

      // Create new single request
      const requestPromise = (async () => {
        try {
          const itemParams = new URLSearchParams({
            'filter[uuid][value][0]': itemUuid,
            'filter[uuid][operator]': 'IN',
            'sale_uuid': saleUuid,
            'page': '1',
          });
          if (reset) {
            itemParams.set('reset', '1');
          }

          const response = await fetch(
            `${config.backendUrl}/api/items?${itemParams.toString()}`,
            config.accessToken ? { headers: { 'access-token': config.accessToken } } : undefined
          );

          if (!response.ok) {
            throw new Error('Failed to fetch item data from bid server');
          }

          const data = await response.json();
          const item = data.data?.[0] || null;

          // Cache with saleUuid key
          itemsCache.current[cacheKey] = item;

          // Clear pending request
          delete pendingItemsRequests.current[cacheKey];

          return item;
        } catch (error) {
          delete pendingItemsRequests.current[cacheKey];
          throw error;
        }
      })();

      pendingItemsRequests.current[cacheKey] = requestPromise;
      return requestPromise;
    }

    // ==================== MULTIPLE UUIDS MODE ====================
    const uuids = itemUuid;

    // Separate cached and uncached items
    const cachedItems = [];
    const uncachedUuids = [];

    uuids.forEach(uuid => {
      const cacheKey = `${uuid}`;
      if (!reset && itemsCache.current[cacheKey]) {
        cachedItems.push(itemsCache.current[cacheKey]);
      } else {
        uncachedUuids.push(uuid);
      }
    });

    // If all items are cached, return immediately
    if (uncachedUuids.length === 0) {
      return cachedItems;
    }

    // Check if uncached UUIDs are part of pending requests
    const stillNeedFetch = [];
    const pendingPromises = [];

    uncachedUuids.forEach(uuid => {
      if (!reset && pendingMultipleItemUuids.current[uuid]) {
        // This UUID is already being fetched
        pendingPromises.push(pendingMultipleItemUuids.current[uuid]);
      } else {
        stillNeedFetch.push(uuid);
      }
    });

    // Wait for any pending items
    if (pendingPromises.length > 0) {
      const pendingItems = await Promise.all(pendingPromises);
      cachedItems.push(...pendingItems.filter(item => item !== null));
    }

    // If no items need fetching, return what we have
    if (stillNeedFetch.length === 0) {
      return cachedItems;
    }

    // ==================== URL LENGTH BATCHING ====================
    // Split UUIDs into batches if URL would be too long (max ~2000 chars safe limit)
    const MAX_URL_LENGTH = 2000;
    const baseUrl = `${config.backendUrl}/api/items?`;
    const baseParams = new URLSearchParams({
      'filter[uuid][operator]': 'IN',
      'page': '1',
    });
    const baseUrlLength = baseUrl.length + baseParams.toString().length;

    // Calculate URL length for a batch of UUIDs
    const calculateUrlLength = (uuidBatch) => {
      let length = baseUrlLength;
      uuidBatch.forEach((uuid, index) => {
        // Format: &filter[uuid][value][INDEX]=UUID
        length += `&filter[uuid][value][${index}]=${uuid}`.length;
      });
      return length;
    };

    // Split UUIDs into batches that fit within URL length limit
    const batches = [];
    let currentBatch = [];

    for (const uuid of stillNeedFetch) {
      const testBatch = [...currentBatch, uuid];
      if (calculateUrlLength(testBatch) > MAX_URL_LENGTH && currentBatch.length > 0) {
        // Current batch would exceed limit, start new batch
        batches.push(currentBatch);
        currentBatch = [uuid];
      } else {
        currentBatch.push(uuid);
      }
    }

    // Add the last batch
    if (currentBatch.length > 0) {
      batches.push(currentBatch);
    }

    // If we have multiple batches, fetch them in parallel
    if (batches.length > 1) {
      const batchPromises = batches.map(batch => {
        const requestKey = `multi:${[...batch].sort().join(',')}`;

        // Check if this batch is already being fetched
        if (pendingItemsRequests.current[requestKey]) {
          return pendingItemsRequests.current[requestKey];
        }

        // Create fetch promise for this batch
        const batchPromise = (async () => {
          try {
            const itemParams = new URLSearchParams({
              'filter[uuid][operator]': 'IN',
              'page': '1',
            });
            if (reset) {
              itemParams.set('reset', '1');
            }

            batch.forEach((uuid, index) => {
              itemParams.append(`filter[uuid][value][${index}]`, uuid);
            });

            const response = await fetch(
              `${config.backendUrl}/api/items?${itemParams.toString()}`,
              config.accessToken ? { headers: { 'access-token': config.accessToken } } : undefined
            );

            if (!response.ok) {
              throw new Error('Failed to fetch item data from bid server');
            }

            const data = await response.json();
            const items = data.data || [];

            // Cache each item individually
            items.forEach(item => {
              if (item && item.uuid) {
                itemsCache.current[`${item.uuid}`] = item;
              }
            });

            // Clear pending individual UUID promises for this batch
            batch.forEach(uuid => {
              delete pendingMultipleItemUuids.current[uuid];
            });

            delete pendingItemsRequests.current[requestKey];

            return items;
          } catch (error) {
            batch.forEach(uuid => {
              delete pendingMultipleItemUuids.current[uuid];
            });
            delete pendingItemsRequests.current[requestKey];
            throw error;
          }
        })();

        // Store pending request
        pendingItemsRequests.current[requestKey] = batchPromise;

        // Create individual promises for each UUID in this batch
        batch.forEach(uuid => {
          pendingMultipleItemUuids.current[uuid] = batchPromise.then(items => {
            return items.find(item => item.uuid === uuid) || null;
          });
        });

        return batchPromise;
      });

      // Wait for all batches to complete
      const batchResults = await Promise.all(batchPromises);
      const allNewItems = batchResults.flat();

      return [...cachedItems, ...allNewItems];
    }

    // ==================== SINGLE BATCH (original logic) ====================
    // Create a request key for this specific set of UUIDs to prevent duplicate bulk requests
    const requestKey = `multi:${[...stillNeedFetch].sort().join(',')}`;

    // Check if this exact set is already being fetched
    if (!reset && pendingItemsRequests.current[requestKey]) {
      const newItems = await pendingItemsRequests.current[requestKey];
      return [...cachedItems, ...newItems];
    }

    // Create new multiple request
    const requestPromise = (async () => {
      try {
        const itemParams = new URLSearchParams({
          'filter[uuid][operator]': 'IN',
          'page': '1',
        });
        if (reset) {
          itemParams.set('reset', '1');
        }

        // Add each UUID as a separate filter value
        stillNeedFetch.forEach((uuid, index) => {
          itemParams.append(`filter[uuid][value][${index}]`, uuid);
        });

        // No sale_uuid for multiple queries

        const response = await fetch(
          `${config.backendUrl}/api/items?${itemParams.toString()}`,
          config.accessToken ? { headers: { 'access-token': config.accessToken } } : undefined
        );

        if (!response.ok) {
          throw new Error('Failed to fetch item data from bid server');
        }

        const data = await response.json();
        const items = data.data || [];

        // Cache each item individually (without saleUuid in key)
        items.forEach(item => {
          if (item && item.uuid) {
            const cacheKey = `${item.uuid}`;
            itemsCache.current[cacheKey] = item;
          }
        });

        // Clear pending individual UUID promises
        stillNeedFetch.forEach(uuid => {
          delete pendingMultipleItemUuids.current[uuid];
        });

        // Clear pending request
        delete pendingItemsRequests.current[requestKey];

        return items;
      } catch (error) {
        // Clear pending requests on error
        stillNeedFetch.forEach(uuid => {
          delete pendingMultipleItemUuids.current[uuid];
        });
        delete pendingItemsRequests.current[requestKey];
        throw error;
      }
    })();

    // Store pending request for the bulk query
    pendingItemsRequests.current[requestKey] = requestPromise;

    // Create individual promises for each UUID being fetched
    // This allows single requests to wait for the multiple request
    stillNeedFetch.forEach(uuid => {
      pendingMultipleItemUuids.current[uuid] = requestPromise.then(items => {
        return items.find(item => item.uuid === uuid) || null;
      });
    });

    const newItems = await requestPromise;
    return [...cachedItems, ...newItems];
  }, [config.backendUrl, config.accessToken]);

  /**
   * Fetch bidder IDs data with caching
   */
  const fetchBidderIds = useCallback(async (saleUuid, userUuid) => {
    if (!config.backendUrl) {
      throw new Error('fetchBidderIds - Missing required configuration (backendUrl)');
    }
    if (!config.accessToken) {
      throw new Error('fetchBidderIds - Missing required configuration (accessToken)');
    }
    if (!saleUuid) {
      throw new Error('fetchBidderIds - Missing required configuration (saleUuid)');
    }
    if (!userUuid) {
      throw new Error('fetchBidderIds - Missing required configuration (userUuid)');
    }

    const cacheKey = `${saleUuid}:${userUuid}`;

    // Return cached data if available
    if (bidderIdsCache.current[cacheKey]) {
      return bidderIdsCache.current[cacheKey];
    }

    // Wait for pending request if exists
    if (pendingBidderIdsRequests.current[cacheKey]) {
      return pendingBidderIdsRequests.current[cacheKey];
    }

    // Create new request
    const requestPromise = (async () => {
      try {
        const url = `${config.backendUrl}/api/bidder_ids?sale_uuid=${saleUuid}&user_uuid=${userUuid}`;
        const response = await fetch(url, {
          headers: { 'access-token': config.accessToken },
        });

        if (!response.ok) {
          throw new Error('Failed to fetch bidder IDs');
        }

        const data = await response.json();

        // Cache the result
        bidderIdsCache.current[cacheKey] = data;

        // Clear pending request
        delete pendingBidderIdsRequests.current[cacheKey];

        return data;
      } catch (error) {
        // Clear pending request on error
        delete pendingBidderIdsRequests.current[cacheKey];
        throw error;
      }
    })();

    // Store pending request
    pendingBidderIdsRequests.current[cacheKey] = requestPromise;

    return requestPromise;
  }, [config.backendUrl, config.accessToken]);

  // items-json: in-memory cache is keyed under both `nid` and `uuid` so callers
  // using either kind of identifier get a hit. localStorage holds the full item
  // only under its `uuid`; a tiny `dc:itemsJsonNid:<nid>` -> `<uuid>` pointer
  // lets nid-based callers (lookup or invalidation) resolve to the uuid entry
  // without re-fetching from the API.

  // Look up an item-json by id from in-memory cache, falling back to localStorage.
  // Hydrates the in-memory cache on a localStorage hit so subsequent calls are instant.
  const getItemJsonFromCache = (id) => {
    const cachedMem = itemsJsonCache.current[id];
    if (cachedMem) return cachedMem;
    // Try LS by the given id first (works if id is a uuid).
    let cachedLs = itemsJsonLs.read(id);
    // If not found and id looks like a nid, resolve via the nid -> uuid pointer.
    if (!cachedLs) {
      const aliasUuid = itemsJsonNidLs.read(id);
      if (aliasUuid) cachedLs = itemsJsonLs.read(aliasUuid);
    }
    if (cachedLs) {
      if (cachedLs.nid) itemsJsonCache.current[cachedLs.nid] = cachedLs;
      if (cachedLs.uuid) itemsJsonCache.current[cachedLs.uuid] = cachedLs;
      itemsJsonCache.current[id] = cachedLs;
    }
    return cachedLs || null;
  };

  // Cache an item-json. In-memory keyed by both nid and uuid; localStorage holds
  // the full item under uuid plus a small nid -> uuid pointer.
  const cacheItemJson = (item) => {
    if (!item) return;
    if (item.nid) {
      itemsJsonCache.current[item.nid] = item;
    }
    if (item.uuid) {
      itemsJsonCache.current[item.uuid] = item;
      itemsJsonLs.write(item.uuid, item);
      if (item.nid) {
        itemsJsonNidLs.write(item.nid, item.uuid);
      }
    }
  };

  /**
   * Fetch item details from items-json endpoint with caching.
   *
   * @param {object} [opts]
   * @param {boolean} [opts.reset]  Bypass memory/localStorage caches AND
   *   forward `?reset=1` to the endpoint so the backend skips its own cache
   *   too (the items-json resource honors `reset`). Triggered by a `?reset=1`
   *   query parameter on the host page (see ItemPage).
   */
  const fetchItemJson = useCallback(async (itemId, backofficeUrl, { reset = false } = {}) => {
    if (!backofficeUrl) {
      throw new Error('fetchItemJson - Missing required configuration (backofficeUrl)');
    }
    if (!itemId) {
      throw new Error('fetchItemJson - Missing required configuration (backoffitemIdiceUrl)');
    }

    if (!reset) {
      // Return cached data if available (memory or localStorage)
      const cached = getItemJsonFromCache(itemId);
      if (cached) {
        return cached;
      }

      // Wait for pending request if exists
      if (pendingItemsJsonRequests.current[itemId]) {
        return pendingItemsJsonRequests.current[itemId];
      }
    }

    // Create new request
    const requestPromise = (async () => {
      try {
        const response = await fetch(
          `${backofficeUrl}/api/items-json/${itemId}${reset ? '?reset=1' : ''}`
        );

        if (!response.ok) {
          throw new Error('Failed to fetch item details');
        }

        const data = await response.json();
        const item = data.data?.[0] || null;

        // Cache the result (memory + localStorage). Also key by the
        // requested itemId in case it doesn't match nid/uuid on the item.
        cacheItemJson(item);
        if (item) itemsJsonCache.current[itemId] = item;

        // Clear pending request
        delete pendingItemsJsonRequests.current[itemId];

        return item;
      } catch (error) {
        // Clear pending request on error
        delete pendingItemsJsonRequests.current[itemId];
        throw error;
      }
    })();

    // Store pending request
    pendingItemsJsonRequests.current[itemId] = requestPromise;

    return requestPromise;
  }, []);

  /**
   * Submit a question about an item (POST request - no caching)
   */
  const submitItemQuestion = useCallback(async (backofficeUrl, questionData) => {
    if (!backofficeUrl) {
      throw new Error('Missing backoffice URL');
    }

    try {
      const response = await fetch(
        `${backofficeUrl}/api/ask-question`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(questionData)
        }
      );

      if (!response.ok) {
        throw new Error('Failed to submit question');
      }

      return await response.json();
    } catch (error) {
      throw error;
    }
  }, []);

  /**
   * Fetch sales from the backoffice public endpoint with caching.
   * Pass `saleNid` to fetch a single sale (`/api/v1.0/sales-public/{nid}`),
   * or `queryString` (already-encoded) to fetch a list (`/api/v1.0/sales-public?...`).
   */
  const fetchSalesPublic = useCallback(async (backofficeUrl, { saleNid, queryString } = {}) => {
    if (!backofficeUrl) {
      throw new Error('fetchSalesPublic - Missing required configuration (backofficeUrl)');
    }

    const url = saleNid
      ? `${backofficeUrl}/api/v1.0/sales-public/${saleNid}`
      : `${backofficeUrl}/api/v1.0/sales-public${queryString ? `?${queryString}` : ''}`;

    const cacheKey = url;

    if (salesPublicCache.current[cacheKey]) {
      return salesPublicCache.current[cacheKey];
    }
    const persisted = salesPublicLs.read(cacheKey);
    if (persisted) {
      salesPublicCache.current[cacheKey] = persisted;
      return persisted;
    }

    if (pendingSalesPublicRequests.current[cacheKey]) {
      return pendingSalesPublicRequests.current[cacheKey];
    }

    const requestPromise = (async () => {
      try {
        const response = await fetch(url);
        if (!response.ok) {
          throw new Error('Failed to fetch sales');
        }
        const data = await response.json();

        salesPublicCache.current[cacheKey] = data;
        salesPublicLs.write(cacheKey, data);
        delete pendingSalesPublicRequests.current[cacheKey];
        return data;
      } catch (error) {
        delete pendingSalesPublicRequests.current[cacheKey];
        throw error;
      }
    })();

    pendingSalesPublicRequests.current[cacheKey] = requestPromise;
    return requestPromise;
  }, []);

  /**
   * Fetch catalogs with caching.
   * Cache key is the full URL so global (no saleNid) and per-sale lists are stored separately.
   */
  const fetchCatalogs = useCallback(async (backofficeUrl, saleNid) => {
    if (!backofficeUrl) {
      throw new Error('fetchCatalogs - Missing required configuration (backofficeUrl)');
    }

    const url = saleNid
      ? `${backofficeUrl}/api/v1.0/catalogs-public?sale_id=${saleNid}&sort=weight`
      : `${backofficeUrl}/api/v1.0/catalogs-public?sort=weight`;

    const cacheKey = url;

    if (catalogsCache.current[cacheKey]) {
      return catalogsCache.current[cacheKey];
    }
    const persisted = catalogsLs.read(cacheKey);
    if (persisted) {
      catalogsCache.current[cacheKey] = persisted;
      return persisted;
    }

    if (pendingCatalogsRequests.current[cacheKey]) {
      return pendingCatalogsRequests.current[cacheKey];
    }

    const requestPromise = (async () => {
      try {
        const response = await fetch(url);
        if (!response.ok) {
          throw new Error('Failed to fetch catalogs');
        }
        const data = await response.json();

        catalogsCache.current[cacheKey] = data;
        catalogsLs.write(cacheKey, data);
        delete pendingCatalogsRequests.current[cacheKey];
        return data;
      } catch (error) {
        delete pendingCatalogsRequests.current[cacheKey];
        throw error;
      }
    })();

    pendingCatalogsRequests.current[cacheKey] = requestPromise;
    return requestPromise;
  }, []);

  /**
   * Fetch sale search results with caching
   */
  const fetchSaleSearch = useCallback(async (backofficeUrl, searchUrl, boAccessToken, { reset = false } = {}) => {
    if (!backofficeUrl) {
      throw new Error('Missing backoffice URL');
    }

    // Use the full search URL as cache key (includes all search parameters)
    const cacheKey = searchUrl;

    if (!reset) {
      // Return cached data if available (memory or localStorage)
      if (saleSearchCache.current[cacheKey]) {
        return saleSearchCache.current[cacheKey];
      }
      const persisted = saleSearchLs.read(cacheKey);
      if (persisted) {
        saleSearchCache.current[cacheKey] = persisted;
        return persisted;
      }

      // Wait for pending request if exists
      if (pendingSaleSearchRequests.current[cacheKey]) {
        return pendingSaleSearchRequests.current[cacheKey];
      }
    }

    // ?reset=1 travels to the API so backend caches are skipped too.
    const requestUrl = reset
      ? `${searchUrl}${searchUrl.includes('?') ? '&' : '?'}reset=1`
      : searchUrl;

    // Create new request
    const requestPromise = (async () => {
      try {
        const response = await fetch(requestUrl, {
          headers: {
            'Authorization': `Bearer ${boAccessToken || ''}`
          }
        });

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.title || 'Failed to fetch search results');
        }

        const data = await response.json();

        // Cache the result (memory + localStorage)
        saleSearchCache.current[cacheKey] = data;
        saleSearchLs.write(cacheKey, data);

        // Clear pending request
        delete pendingSaleSearchRequests.current[cacheKey];

        return data;
      } catch (error) {
        // Clear pending request on error
        delete pendingSaleSearchRequests.current[cacheKey];
        throw error;
      }
    })();

    // Store pending request
    pendingSaleSearchRequests.current[cacheKey] = requestPromise;

    return requestPromise;
  }, []);

  /**
   * Fetch multiple items by IDs (NIDs or UUIDs) with individual caching.
   * Shares the same cache as fetchItemJson since both return the same item structure.
   * Items are cached by both `nid` and `uuid` so callers can look up by either key.
   *
   * Splits very long ID lists into multiple parallel GET requests so the URL
   * stays under the safe browser/server limit (~2000 chars).
   *
   * Singleton Pattern: Prevents duplicate parallel requests for the same batch.
   */
  const fetchItemsByIds = useCallback(async (backofficeUrl, ids, language) => {
    if (!backofficeUrl || !ids || ids.length === 0) {
      throw new Error('Missing required parameters');
    }

    // Separate cached and uncached IDs.
    // Cache is keyed by both nid and uuid; localStorage is checked as a fallback.
    const cachedItems = [];
    const uncachedIds = [];

    ids.forEach(id => {
      const cached = getItemJsonFromCache(id);
      if (cached) {
        cachedItems.push(cached);
      } else {
        uncachedIds.push(id);
      }
    });

    // If all items are cached, return them immediately
    if (uncachedIds.length === 0) {
      return {
        data: cachedItems,
        count: cachedItems.length
      };
    }

    // ==================== URL LENGTH BATCHING ====================
    // Split IDs into batches if URL would be too long (max ~2000 chars safe limit)
    // Pick query param based on input format: numeric NIDs use `ids=`, UUIDs use `uuids=`.
    const isUuidInput = uncachedIds.some(id => !/^\d+$/.test(String(id)));
    const idParamName = isUuidInput ? 'uuids' : 'ids';
    const MAX_URL_LENGTH = 2000;
    const baseUrl = `${backofficeUrl}/api/items-json?`;
    const baseParams = new URLSearchParams({
      json_type: 'web',
      language: language ?? '',
    });
    // +1 for "&", +1 for "=", + length of the param name
    const baseUrlLength = baseUrl.length + baseParams.toString().length + idParamName.length + 2;

    // Calculate URL length for a batch of IDs (comma-joined, encoded)
    const calculateUrlLength = (idBatch) =>
      baseUrlLength + encodeURIComponent(idBatch.join(',')).length;

    const batches = [];
    let currentBatch = [];

    for (const id of uncachedIds) {
      const testBatch = [...currentBatch, id];
      if (calculateUrlLength(testBatch) > MAX_URL_LENGTH && currentBatch.length > 0) {
        batches.push(currentBatch);
        currentBatch = [id];
      } else {
        currentBatch.push(id);
      }
    }
    if (currentBatch.length > 0) {
      batches.push(currentBatch);
    }

    // Fetch one batch with singleton de-duplication
    const fetchBatch = (batch) => {
      const cacheKey = `${[...batch].sort().join(',')}-${language}`;

      if (pendingItemsByIdsRequests.current[cacheKey]) {
        return pendingItemsByIdsRequests.current[cacheKey];
      }

      const batchPromise = (async () => {
        try {
          const params = new URLSearchParams({
            json_type: 'web',
            [idParamName]: batch.join(','),
            language: language ?? '',
          });

          const response = await fetch(
            `${backofficeUrl}/api/items-json?${params.toString()}`
          );

          if (!response.ok) {
            throw new Error('Failed to fetch item details');
          }

          const result = await response.json();

          // Cache each item by both its nid and uuid (memory + localStorage)
          if (result.data && Array.isArray(result.data)) {
            result.data.forEach(cacheItemJson);
          }

          delete pendingItemsByIdsRequests.current[cacheKey];
          return result;
        } catch (error) {
          delete pendingItemsByIdsRequests.current[cacheKey];
          throw error;
        }
      })();

      pendingItemsByIdsRequests.current[cacheKey] = batchPromise;
      return batchPromise;
    };

    // Fire all batches in parallel
    const batchResults = await Promise.all(batches.map(fetchBatch));
    const fetchedItems = batchResults.flatMap(r => r.data || []);

    const allItems = [...cachedItems, ...fetchedItems];

    return {
      data: allItems,
      count: allItems.length
    };
  }, []);

  /**
   * Fetch sale info from backoffice with caching
   */
  const fetchSaleInfo = useCallback(async (saleNid, backofficeUrl, { reset = false } = {}) => {
    if (!backofficeUrl || !saleNid) {
      throw new Error('Missing required parameters');
    }

    if (!reset) {
      // Return cached data if available
      if (saleInfoCache.current[saleNid]) {
        return saleInfoCache.current[saleNid];
      }

      // Wait for pending request if exists
      if (pendingSaleInfoRequests.current[saleNid]) {
        return pendingSaleInfoRequests.current[saleNid];
      }
    }

    // Create new request
    const requestPromise = (async () => {
      try {
        const response = await fetch(
          `${backofficeUrl}/admin/get-sale-info/${saleNid}${reset ? '?reset=1' : ''}`
        );

        if (!response.ok) {
          throw new Error('Failed to fetch sale information');
        }

        const data = await response.json();

        // Cache the result
        saleInfoCache.current[saleNid] = data;

        // Clear pending request
        delete pendingSaleInfoRequests.current[saleNid];

        return data;
      } catch (error) {
        // Clear pending request on error
        delete pendingSaleInfoRequests.current[saleNid];
        throw error;
      }
    })();

    // Store pending request
    pendingSaleInfoRequests.current[saleNid] = requestPromise;

    return requestPromise;
  }, []);

  /**
   * Fetch bidding status from backoffice with caching (2 minutes TTL)
   *
   * Singleton Pattern: If multiple parallel requests are made for the same data,
   * only ONE fetch request is executed. All callers receive the same promise and
   * wait for the same result, preventing duplicate API calls.
   */
  const fetchBiddingStatus = useCallback(async (saleUuid, userUuid, backofficeUrl, accessToken) => {
    if (!backofficeUrl || !saleUuid || !userUuid || !accessToken) {
      throw new Error('Missing required parameters');
    }

    const cacheKey = `${saleUuid}:${userUuid}`;

    // STEP 1: Check if cached data is available and not expired (2 minutes = 120000ms)
    const cachedData = biddingStatusCache.current[cacheKey];
    if (cachedData && cachedData.timestamp && (Date.now() - cachedData.timestamp < 120000)) {
      return cachedData.data;
    }

    // STEP 2: SINGLETON CHECK - If there's already a pending request for this key,
    // return that same promise instead of creating a new fetch.
    // This ensures parallel calls share the same request.
    if (pendingBiddingStatusRequests.current[cacheKey]) {
      return pendingBiddingStatusRequests.current[cacheKey];
    }

    // STEP 3: No cached data and no pending request - create new request
    const requestPromise = (async () => {
      try {
        const url = `${backofficeUrl}/api/v1.0/bidding-status?sale_uuid=${saleUuid}&user_uuid=${userUuid}`;
        const response = await fetch(url, {
          headers: { 'access-token': accessToken },
        });

        if (!response.ok) {
          throw new Error('Failed to fetch bidding status');
        }

        const responseData = await response.json();

        // Cache the result with timestamp for future requests
        biddingStatusCache.current[cacheKey] = {
          data: responseData,
          timestamp: Date.now()
        };

        // Clear pending request now that we have the result cached
        delete pendingBiddingStatusRequests.current[cacheKey];

        return responseData;
      } catch (error) {
        // Clear pending request on error so future calls can retry
        delete pendingBiddingStatusRequests.current[cacheKey];
        throw error;
      }
    })();

    // STEP 4: Store the promise BEFORE any await so parallel calls can find it
    pendingBiddingStatusRequests.current[cacheKey] = requestPromise;

    return requestPromise;
  }, []);

  /**
   * Generic PATCH request to /api/items (Backend Server)
   * Used for: favorite toggle, buy now, and other item mutations
   */
  const patchItemsBs = useCallback(async (itemId, data, backendUrl, accessToken) => {
    if (!backendUrl || !accessToken || !itemId) {
      throw new Error('Missing required parameters');
    }

    try {
      const response = await fetch(
        `${backendUrl}/api/items/${itemId}`,
        {
          method: 'PATCH',
          headers: {
            'Content-Type': 'application/json',
            'access-token': accessToken,
          },
          body: JSON.stringify(data)
        }
      );

      if (!response.ok) {
        throw new Error('Failed to update item');
      }

      return await response.json();
    } catch (error) {
      throw error;
    }
  }, []);

  /**
   * Invalidate cached data (useful after mutations like placing a bid)
   *
   * @param {string|string[]} itemUuid - Single UUID string or array of UUID strings
   * @param {string} saleUuid - Sale UUID (optional when invalidating multiple items)
   */
  const invalidateItem = useCallback((itemUuid, saleUuid) => {
    const isMultiple = Array.isArray(itemUuid);

    if (isMultiple) {
      // Invalidate each item's cache (without saleUuid)
      itemUuid.forEach(uuid => {
        delete itemsCache.current[uuid];
      });
    } else {
      // Invalidate both cache formats for single item
      if (saleUuid) {
        delete itemsCache.current[`${saleUuid}:${itemUuid}`];
      }
      delete itemsCache.current[itemUuid];
    }
  }, []);

  const invalidateSale = useCallback((saleUuid) => {
    delete salesCache.current[saleUuid];
    saleBsLs.remove(saleUuid);
  }, []);

  const invalidateBidderIds = useCallback((saleUuid, userUuid) => {
    const cacheKey = `${saleUuid}:${userUuid}`;
    delete bidderIdsCache.current[cacheKey];
  }, []);

  const invalidateItemJson = useCallback((itemId) => {
    const item = itemsJsonCache.current[itemId];
    // Resolve nid -> uuid via in-memory item or the LS pointer (covers cold caches).
    const uuid = item?.uuid || itemsJsonNidLs.read(itemId) || itemId;
    const nid = item?.nid || (uuid !== itemId ? itemId : null);
    // Memory is keyed by both nid + uuid — clear every alias.
    const memKeys = new Set([itemId, uuid]);
    if (nid) memKeys.add(nid);
    memKeys.forEach(key => key && delete itemsJsonCache.current[key]);
    // localStorage: drop the full uuid-keyed entry and the nid -> uuid pointer.
    itemsJsonLs.remove(uuid);
    if (nid) itemsJsonNidLs.remove(nid);
  }, []);

  const invalidateSaleSearch = useCallback((searchUrl) => {
    if (searchUrl) {
      // Invalidate specific search URL
      delete saleSearchCache.current[searchUrl];
      saleSearchLs.remove(searchUrl);
    } else {
      // Clear all search cache if no URL provided
      saleSearchCache.current = {};
      saleSearchLs.clearAll();
    }
  }, []);

  const invalidateSaleInfo = useCallback((saleNid) => {
    if (saleNid) {
      delete saleInfoCache.current[saleNid];
    } else {
      // Clear all sale info cache if no NID provided
      saleInfoCache.current = {};
    }
  }, []);

  const invalidateBiddingStatus = useCallback((saleUuid, userUuid) => {
    if (saleUuid && userUuid) {
      const cacheKey = `${saleUuid}:${userUuid}`;
      delete biddingStatusCache.current[cacheKey];
    } else {
      // Clear all bidding status cache if no parameters provided
      biddingStatusCache.current = {};
    }
  }, []);

  // Admin-only: wipe all in-memory and localStorage caches for items and sales.
  const clearItemsAndSalesCache = useCallback(() => {
    salesCache.current = {};
    itemsCache.current = {};
    itemsJsonCache.current = {};
    saleSearchCache.current = {};
    saleInfoCache.current = {};
    catalogsCache.current = {};
    salesPublicCache.current = {};

    itemsJsonLs.clearAll();
    itemsJsonNidLs.clearAll();
    saleSearchLs.clearAll();
    catalogsLs.clearAll();
    salesPublicLs.clearAll();
    saleBsLs.clearAll();
  }, []);

  // Listen for remote cache-invalidation events pushed by the backoffice via
  // Pusher. See docs/remote-cache-invalidation.md for the wire format.
  //
  // Each event carries:
  //   - `uuid`     — globally-unique per-message id, used to dedupe across
  //                  the live Pusher subscription AND the bootstrap catchup
  //                  endpoint (the same message can arrive twice if the
  //                  catchup window overlaps with live delivery), AND across
  //                  multiple originating servers (backoffices, bid-server).
  //   - `created`  — server-side Unix timestamp of the broadcast. We track
  //                  the most recent one in localStorage as the "since"
  //                  cursor for the next catchup call.
  //
  // We deliberately avoid coupling the client to any one server's
  // monotonic id sequence — when two servers can broadcast on the same
  // channel, their numeric ids collide. UUID + timestamp survives that.
  useEffect(() => {
    if (!config.pusherKey?.key || !config.siteName || !config.env) return;

    pusherService.init({
      key: config.pusherKey.key,
      cluster: config.pusherKey.cluster,
      authEndpoint: `${config.backendUrl}/api/pusher_auth`,
      accessToken: config.accessToken || '',
    });

    // Channel name mirrors what the backoffice builds from
    // server_general_get_site_login_name() + server_general_get_env_prefix(),
    // routed through the serverless. See docs/remote-cache-invalidation.md.
    //
    // Deliberately NOT prefixed with `cache-` / `private-cache-`:
    // those prefixes turn a Pusher channel into a "cache channel"
    // that auto-replays the last ≤30-min event to every new
    // subscriber. We already have an explicit AQ-backed catch-up
    // endpoint that covers a 1-hour window, so we don't want
    // Pusher's incidental short-window replay on top.
    const channelName = `invalidation-cache-${config.siteName}-${config.env}`;
    pusherService.subscribeChannel(channelName, ['cache__invalidate']);

    // localStorage key — scoped to site + env so a browser used across
    // tenants or environments doesn't replay events from the wrong one.
    // Stores the server-side `created` timestamp of the most recent
    // payload we've applied; the next bootstrap catchup uses it as the
    // "since" cursor.
    const lastSeenAtKey = `dc:lastCacheSeenAt:${config.siteName}-${config.env}`;
    const readLastSeenAt = () => {
      const raw = localStorage.getItem(lastSeenAtKey);
      const n = raw ? parseInt(raw, 10) : 0;
      return Number.isFinite(n) && n > 0 ? n : 0;
    };
    const writeLastSeenAt = (ts) => {
      const n = Number(ts);
      if (!Number.isFinite(n) || n <= 0) return;
      // Only move forward — out-of-order Pusher delivery shouldn't roll us back.
      if (n > readLastSeenAt()) {
        localStorage.setItem(lastSeenAtKey, String(n));
      }
    };

    // In-memory UUID dedupe — guards against the same payload arriving
    // twice (once live via Pusher, once via the bootstrap catchup that
    // overlaps the live delivery window). Bounded so it can't grow
    // unbounded across a long-running session.
    const seenUuids = new Set();
    const SEEN_UUIDS_CAP = 500;
    const SEEN_UUIDS_KEEP = 200;

    // Apply one server payload to local cache. Same body for live Pusher
    // delivery and for the bootstrap catchup fetch.
    const applyPayload = (payload) => {
      if (!payload) return;
      if (payload.uuid) {
        if (seenUuids.has(payload.uuid)) return;
        seenUuids.add(payload.uuid);
        if (seenUuids.size > SEEN_UUIDS_CAP) {
          // Keep the most recently added uuids — Set preserves insertion order.
          const recent = Array.from(seenUuids).slice(-SEEN_UUIDS_KEEP);
          seenUuids.clear();
          recent.forEach((u) => seenUuids.add(u));
        }
      }
      if (payload.all) {
        clearItemsAndSalesCache();
      } else {
        if (Array.isArray(payload.items)) {
          payload.items.forEach((id) => {
            invalidateItemJson(id);
            invalidateItem(id);
          });
        }
        if (Array.isArray(payload.sales)) {
          payload.sales.forEach((id) => {
            invalidateSale(id);
            invalidateSaleInfo(id);
          });
          // Sale-search results embed sale data — drop them all on any sale change.
          invalidateSaleSearch();
        }
      }
      writeLastSeenAt(payload.created);
    };

    pusherService.on('cache__invalidate', applyPayload);

    // Bootstrap: fetch anything we missed while offline (server only keeps
    // 1h of history since older entries are stale anyway).
    const catchUp = async () => {
      const since = readLastSeenAt();
      try {
        const url = `${config.siteData.backoffice_url}/api/v1.0/invoke-function-public/cache_invalidate_messages?params[0]=${since}`;
        const headers = { Accept: 'application/json' };
        const resp = await fetch(url, { headers, credentials: 'omit' });
        if (!resp.ok) return;
        const body = await resp.json();
        // invoke-function wraps scalar / array returns: shape is either
        // { data: [{ serverTime, messages }] } or { data: { serverTime, messages } }.
        const result = Array.isArray(body?.data) ? body.data[0] : body?.data;
        if (!result || !Array.isArray(result.messages)) return;
        result.messages.forEach(applyPayload);
        // Advance the cursor to the server's "now" — saves us re-fetching
        // any new event that landed live during the catchup roundtrip
        // (those still hit applyPayload and the UUID dedupe handles
        // double-processing safely).
        if (typeof result.serverTime === 'number') {
          writeLastSeenAt(result.serverTime);
        }
      } catch (e) {
        // Catchup is best-effort — a failure here just means stale data
        // until the next mutation or page reload. Don't disrupt the app.
        // eslint-disable-next-line no-console
        console.warn('[DataCache] cache-invalidate catchup failed:', e);
      }
    };
    catchUp();

    return () => {
      pusherService.off('cache__invalidate', applyPayload);
      pusherService.unsubscribeChannel(channelName);
    };
  }, [
    config.pusherKey,
    config.backendUrl,
    config.siteData?.backoffice_url,
    config.siteName,
    config.env,
    config.accessToken,
    clearItemsAndSalesCache,
    invalidateItem,
    invalidateItemJson,
    invalidateSale,
    invalidateSaleInfo,
    invalidateSaleSearch,
  ]);

  const value = {
    fetchSale,
    fetchItem,
    fetchBidderIds,
    fetchItemJson,
    submitItemQuestion,
    fetchSaleSearch,
    fetchItemsByIds,
    fetchSaleInfo,
    fetchBiddingStatus,
    fetchCatalogs,
    fetchSalesPublic,
    patchItemsBs,
    invalidateItem,
    invalidateSale,
    invalidateBidderIds,
    invalidateItemJson,
    invalidateSaleSearch,
    invalidateSaleInfo,
    invalidateBiddingStatus,
    clearItemsAndSalesCache,
  };

  return (
    <DataCacheContext.Provider value={value}>
      {children}
    </DataCacheContext.Provider>
  );
};

/**
 * Hook to use the data cache
 */
export const useDataCache = () => {
  const context = useContext(DataCacheContext);
  if (!context) {
    throw new Error('useDataCache must be used within a DataCacheProvider');
  }
  return context;
};