import React, { useState, useEffect, useContext, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { useToast, Spinner } from '@chakra-ui/react';
import { formatCurrencyAmount, ConfigContext } from '../config/Config';
import { useTranslation } from 'react-i18next';

const LaptopIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <rect x="3" y="4" width="18" height="12" rx="2" />
    <line x1="1" y1="20" x2="23" y2="20" />
  </svg>
);

const MyCredit = ({ accessToken, userUuid, saleUuid, currency }) => {
  const { t } = useTranslation();
  const [isSubmitting, setIsSubmitting] = useState(false);
  // TODO(circuit): replace Chakra useToast with a native skill toast.
  const toast = useToast();
  const [isLoading, setIsLoading] = useState(true);
  const [creditInfo, setCreditInfo] = useState(null);
  const [bidderInfo, setBidderInfo] = useState(null);
  const [amountInput, setAmountInput] = useState(creditInfo?.amount || '');
  const [approvedAmount, setApprovedAmount] = useState(false);
  const config = useContext(ConfigContext);
  const isAmountChanged = amountInput !== (creditInfo?.amount || '');

  // Bidder pill is portaled into the enclosing card-head's slot div so it
  // appears on the right of "Manage Your Bidding Limits" instead of inside
  // the card body. The slot is owned by the parent (MyBids); we find it
  // via a callback ref on our own root element.
  const [bidderSlot, setBidderSlot] = useState(null);
  const rootRef = useCallback((el) => {
    if (!el) {
      setBidderSlot(null);
      return;
    }
    const card = el.closest('.bid-limits-card');
    const slot = card ? card.querySelector('.card-head__bidder-slot') : null;
    setBidderSlot(slot);
  }, []);

  useEffect(() => {
    const fetchCreditInfo = async () => {
      try {
        const response = await fetch(`${config.backendUrl}/api/v1.0/bidder_ids?filter[bidder_type]=website&user_uuid=${userUuid}&sale_uuid=${saleUuid}`, {
          headers: { 'access-token': accessToken },
        });
        if (!response.ok) return;
        const data = await response.json();
        if (data.count === 0) return;
        setBidderInfo(data.data[0]);
        const liveCredit = data.data[0].live_credit;
        setApprovedAmount(liveCredit);
      } catch (error) {
        toast({
          title: t('myCredit.error'),
          description: error.title,
          status: 'error',
          duration: 9000,
          isClosable: true,
        });
      } finally {
        setIsLoading(false);
      }
    };

    fetchCreditInfo();
  }, [accessToken, userUuid, saleUuid, toast, config, t]);

  useEffect(() => {
    const fetchCreditInfo = async () => {
      if (!bidderInfo) return;
      try {
        const response = await fetch(`${config.backendUrl}/api/credit_requests?sort=-id&user_uuid=${userUuid}&sale_uuid=${saleUuid}`, {
          headers: { 'access-token': accessToken },
        });
        if (!response.ok) return;
        const data = await response.json();
        if (data.count === 0) return;
        const amount = data.data[0].amount;
        setCreditInfo(data.data[0]);
        setAmountInput(amount);
      } catch (error) {
        toast({
          title: t('myCredit.error'),
          description: error.title,
          status: 'error',
          duration: 9000,
          isClosable: true,
        });
      } finally {
        setIsLoading(false);
      }
    };

    fetchCreditInfo();
  }, [accessToken, userUuid, saleUuid, toast, config, bidderInfo, t]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    let creditRequestData = {
      amount: amountInput,
      sale_uuid: saleUuid,
      user_uuid: userUuid,
    };
    let method = 'POST';
    let url = `${config.backendUrl}/api/credit_requests`;
    if (creditInfo && creditInfo.id && creditInfo.status !== 'approved') {
      method = 'PATCH';
      url = `${config.backendUrl}/api/credit_requests/${creditInfo.id}`;
      creditRequestData = { amount: amountInput };
    }

    try {
      const response = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'access-token': accessToken,
        },
        body: JSON.stringify(creditRequestData),
      });

      const responseData = await response.json();

      if (response.ok) {
        setCreditInfo(responseData.data[0]);
        toast({
          title: t('myCredit.creditRequestSubmitted'),
          description: t('myCredit.creditRequestDescription', { amount: formatCurrencyAmount(responseData.data[0].amount, currency) }),
          status: 'success',
          duration: 9000,
          isClosable: true,
        });
      } else {
        toast({
          title: t('myCredit.error'),
          description: responseData.title || t('myCredit.errorSubmittingCreditRequest'),
          status: 'error',
          duration: 9000,
          isClosable: true,
        });
      }
    } catch (error) {
      toast({
        title: t('myCredit.error'),
        description: error.message || t('myCredit.generalError'),
        status: 'error',
        duration: 9000,
        isClosable: true,
      });
    } finally {
      setIsSubmitting(false);
    }
  };

  let formHeading = t('myCredit.formHeading');
  let buttonLabel = t('myCredit.buttonLabel');
  let creditStatusMessage = t('myCredit.creditStatusMessage');
  let pendingNoteVariant = 'warning';

  if (creditInfo && creditInfo.status === 'pending') {
    formHeading = t('myCredit.pendingFormHeading');
    buttonLabel = t('myCredit.pendingButtonLabel');
    creditStatusMessage = t('myCredit.pendingCreditStatusMessage', {
      amount: formatCurrencyAmount(creditInfo.amount, currency),
    });
  }

  if (creditInfo && creditInfo.status === 'approved') {
    pendingNoteVariant = 'success';
    formHeading = t('myCredit.approvedFormHeading');
    buttonLabel = t('myCredit.approvedButtonLabel');
    if (String(approvedAmount) === '-1') {
      creditStatusMessage = t('myCredit.approvedCreditStatusMessageUnlimited');
    } else {
      const requestedAmount = creditInfo.amount;
      const currentCredit = bidderInfo.live_credit;

      if (requestedAmount !== currentCredit) {
        creditStatusMessage = t('myCredit.approvedCreditStatusMessageModified', {
          amount_request: formatCurrencyAmount(requestedAmount, currency),
          current_amount: formatCurrencyAmount(currentCredit, currency),
        });
      } else {
        creditStatusMessage = t('myCredit.approvedCreditStatusMessage', {
          amount_request: formatCurrencyAmount(requestedAmount, currency),
        });
      }
    }
  }

  if (isLoading) {
    return <p className="bid-limits__loading">{t('myCredit.loading')}</p>;
  }

  if (!bidderInfo) return null;

  const BidderPill = (
    <div className="my-credit__bidder">
      <LaptopIcon />
      <span>{t('myCredit.bidderNumber', { number: bidderInfo.bidder_number })}</span>
    </div>
  );
  const bidderPortal = bidderSlot ? createPortal(BidderPill, bidderSlot) : null;

  // Rejected request
  if (creditInfo && creditInfo.status === 'rejected') {
    return (
      <div className="my-credit" ref={rootRef}>
        {bidderPortal}
        <div className="cream-note cream-note--error" role="alert">
          {String(approvedAmount) === '-1'
            ? t('myCredit.rejectedCreditStatusMessageUnlimited')
            : t('myCredit.rejectedCreditStatusMessage', { amount: formatCurrencyAmount(approvedAmount, currency) })}
        </div>
      </div>
    );
  }

  // Default + approved/no-request branches collapse — both show the same
  // bidder + success-note structure; the form only renders below when
  // String(approvedAmount) !== '-1' (i.e. credit is not unlimited). When the
  // form IS shown, the current-limit status moves INTO the row's left
  // slot (instead of sitting above as a cream-note) so the row mirrors
  // the .bid-limit-row pattern in Personal Bidding Limits.
  const showForm = String(approvedAmount) !== '-1';
  const currentLimitMessage = String(approvedAmount) === '-1'
    ? t('myCredit.approvedCreditStatusMessageUnlimited')
    : t('myCredit.approvedCreditStatusMessageNoRequest', { amount: formatCurrencyAmount(approvedAmount, currency) });

  return (
    <div className="my-credit" ref={rootRef}>
      {bidderPortal}

      {!showForm && (
        <div className="cream-note cream-note--success" role="status">
          {currentLimitMessage}
        </div>
      )}

      {showForm && (
        <form onSubmit={handleSubmit} className="credit-request-form">
          <h3 className="bid-limits__section-title">{formHeading}</h3>
          <p className="bid-limits__help">
            {t('myCredit.instructions')} {t('myCredit.noCommasOrDecimals')}
          </p>

          {creditInfo && (
            <div className={`cream-note cream-note--${pendingNoteVariant}`} role="status">
              {creditStatusMessage}
            </div>
          )}

          <div className="bid-limit-row credit-request-row">
            <div className="credit-request-row__current">
              {currentLimitMessage}
            </div>

            <label
              htmlFor={`credit-request-${saleUuid}`}
              className="credit-request-row__label"
            >
              {t('myCredit.creditRequestLabel', { currency })}
              <span className="req">*</span>
            </label>

            <input
              id={`credit-request-${saleUuid}`}
              type="number"
              min="1"
              max="2147483647"
              value={amountInput}
              onChange={(e) => setAmountInput(e.target.value)}
              required
              className="field-input bid-limit-row__input"
            />

            <button
              type="submit"
              className="bid-limit-submit"
              disabled={!isAmountChanged || isSubmitting}
            >
              {isSubmitting ? <Spinner size="sm" /> : buttonLabel}
            </button>
          </div>
        </form>
      )}
    </div>
  );
};

export default MyCredit;
