import React, { useState, useEffect } from 'react';
import {
  Box,
  Stack,
  Checkbox,
  Text,
  Collapse,
  Divider
} from '@chakra-ui/react';
import AddressForm from './AddressForm';

const PaymentAddressSection = ({
  savedAddresses = [],
  onAddressSelect,
  namePrefixes = [],
  defaultCountry = 'US',
  showFormInitially = false
}) => {
  const [showBillingForm, setShowBillingForm] = useState(showFormInitially);
  const [useDifferentBilling, setUseDifferentBilling] = useState(showFormInitially);

  useEffect(() => {
    setShowBillingForm(showFormInitially);
    setUseDifferentBilling(showFormInitially);
  }, [showFormInitially]);

  const handleBillingAddressSave = (addressData) => {
    onAddressSelect({
      ...addressData,
      address_types: ['billing'],
      default_address: false
    });
    setShowBillingForm(false);
  };

  return (
    <Stack spacing={4} width="100%">
      {!showFormInitially && (
        <Box>
          <Checkbox
            isChecked={useDifferentBilling}
            onChange={(e) => {
              setUseDifferentBilling(e.target.checked);
              setShowBillingForm(e.target.checked);
            }}
          >
            Use different billing address
          </Checkbox>
        </Box>
      )}

      <Collapse in={showBillingForm || showFormInitially}>
        <Box mt={4}>
          <Divider mb={4} />
          <Text fontSize="lg" mb={4}>Billing Address</Text>
          <AddressForm
            address={{
              address: {},
              address_types: ['billing'],
              default_address: false
            }}
            onSave={handleBillingAddressSave}
            namePrefixes={namePrefixes}
            defaultCountry={defaultCountry}
            isBillingAddress={true}
            hideDefaultSelector={true}
            hideAddressTypes={true}
          />
        </Box>
      </Collapse>
    </Stack>
  );
};

export default PaymentAddressSection;