import React from 'react';
import {
  Box,
  Table,
  Thead,
  Tbody,
  Tr,
  Th,
  Td,
  Text,
  Badge,
  Flex
} from '@chakra-ui/react';
import { useTranslation } from 'react-i18next';
import { formatCurrencyAmount } from '../config/Config';

const TransactionList = ({ invoice }) => {
  const { t } = useTranslation();

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };
  

  return (
    <Box mt={4}>
      <Text fontWeight="medium" mb={4}>
        {t('billing.transactions')} ({invoice.transactions && invoice.transactions.length})
      </Text>

      {!invoice.transactions || invoice.transactions.length === 0 ? (
        <Box textAlign="center" py={4} bg="gray.50" rounded="md">
          <Text color="gray.500">{t('billing.noTransactionsMessage')}</Text>
        </Box>
      ) : (
        <>
          {/* Desktop Table */}
          <Box display={{ base: 'none', md: 'block' }}>
            <Table variant="simple" size="sm">
              <Thead>
                <Tr>
                  <Th>{t('billing.transactionDate')}</Th>
                  <Th>{t('billing.method')}</Th>
                  <Th>{t('billing.description')}</Th>
                  <Th isNumeric>{t('billing.amount')}</Th>
                </Tr>
              </Thead>
              <Tbody>
                {invoice.transactions.map((transaction) => (
                  <Tr key={transaction.id}>
                    <Td>{formatDate(transaction.date)}</Td>
                    <Td>
                      <Badge colorScheme="gray">
                        {t(`billing.paymentMethods.${transaction.method}`, { defaultValue: transaction.method.replace(/_/g, ' ') })}
                      </Badge>
                    </Td>
                    <Td>{transaction.description}</Td>
                    <Td isNumeric>
                      {formatCurrencyAmount(transaction.amount, invoice.currency, 2)}
                    </Td>
                  </Tr>
                ))}
                <Tr fontWeight="bold">
                  <Td colSpan={3}>{t('billing.totalPaid')}</Td>
                  <Td isNumeric>
                    {formatCurrencyAmount(invoice.paidAmount, invoice.currency, 2)}
                  </Td>
                </Tr>
                {invoice.remainingAmount > 0 && (
                  <Tr color="red.500" fontWeight="bold">
                    <Td colSpan={3}>{t('billing.remaining')}</Td>
                    <Td isNumeric>
                      {formatCurrencyAmount(invoice.remainingAmount, invoice.currency, 2)}
                    </Td>
                  </Tr>
                )}
              </Tbody>
            </Table>
          </Box>

          {/* Mobile Cards */}
          <Box display={{ base: 'block', md: 'none' }}>
            {invoice.transactions.map((transaction) => (
              <Box key={transaction.id} bg="gray.50" p={3} rounded="md" mb={2}>
                <Flex justify="space-between" align="start" mb={2}>
                  <Box>
                    <Text fontSize="sm" fontWeight="semibold">
                      {formatDate(transaction.date)}
                    </Text>
                    <Badge colorScheme="gray" size="sm" mt={1}>
                      {t(`billing.paymentMethods.${transaction.method}`, { defaultValue: transaction.method.replace(/_/g, ' ') })}
                    </Badge>
                  </Box>
                  <Text fontWeight="bold">
                    {formatCurrencyAmount(transaction.amount, invoice.currency, 2)}
                  </Text>
                </Flex>
                <Text fontSize="sm" color="gray.700">
                  {transaction.description}
                </Text>
              </Box>
            ))}
            
            {/* Mobile Summary */}
            <Box bg="blue.50" p={3} rounded="md" mt={3}>
              <Flex justify="space-between" fontWeight="bold">
                <Text>{t('billing.totalPaid')}</Text>
                <Text>{formatCurrencyAmount(invoice.paidAmount, invoice.currency, 2)}</Text>
              </Flex>
              {invoice.remainingAmount > 0 && (
                <Flex justify="space-between" color="red.500" fontWeight="bold" mt={2}>
                  <Text>{t('billing.remaining')}</Text>
                  <Text>{formatCurrencyAmount(invoice.remainingAmount, invoice.currency, 2)}</Text>
                </Flex>
              )}
            </Box>
          </Box>
        </>
      )}
    </Box>
  );
};

export default TransactionList;