import React, { useContext, useState } from 'react';
// useToast still Chakra (TODO native skill toast).
import { useToast } from '@chakra-ui/react';
import { Combine } from 'lucide-react';
import { useTranslation } from 'react-i18next';
import fetchData from '../utils/Util';
import { ConfigContext } from '../config/Config';
import { CircuitDropdown } from './CircuitDropdown';
import { PortalTooltip } from './PortalTooltip';

const CloseSmall = () => (
  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <line x1="18" y1="6" x2="6" y2="18" />
    <line x1="6" y1="6" x2="18" y2="18" />
  </svg>
);

const ExplanationTooltip = ({ children, title, main, example }) => (
  <PortalTooltip
    content={
      <>
        <strong className="group-tooltip__title">{title}</strong>
        <p>{main}</p>
        <p>{example}</p>
      </>
    }
  >
    {children}
  </PortalTooltip>
);

const AltLotsTooltip = ({ children, title, lots }) => (
  <PortalTooltip
    content={
      <>
        <strong className="group-tooltip__title">{title}</strong>
        <span className="group-tooltip__lots">
          {lots.map((lot, idx) => (
            <span key={`${lot}-${idx}`} className="group-tooltip__lot">
              {lot}
            </span>
          ))}
        </span>
      </>
    }
  >
    {children}
  </PortalTooltip>
);

const GroupEditor = ({ bid, item, onGroupUpdate, itemsBidData }) => {
  const { t } = useTranslation();
  const [isEditing, setIsEditing] = useState(false);
  const [selectedGroup, setSelectedGroup] = useState(bid?.bids_group_name || '');
  const toast = useToast();
  const config = useContext(ConfigContext);

  const groups = ['none', 'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j'];

  const hasNonPausedItemsInGroup = (groupName) => {
    if (!groupName) return false;

    const groupBids = itemsBidData?.flatMap(sale =>
      sale.data.flatMap(it => [
        ...(it.bid || []),
        ...(it.book_bid || []),
        ...(it.agent_bid || []),
      ])
    ).filter(b => b.bids_group_name === groupName);

    return groupBids?.some(groupBid => {
      const bidItem = itemsBidData?.flatMap(sale => sale.data)
        .find(it => it.uuid === groupBid.item_uuid);
      return bidItem?.status !== 'paused';
    });
  };

  const handleSave = async () => {
    try {
      const url = `${config.backendUrl}/api/bids/${bid.id}`;
      const bidData = { bids_group_name: !selectedGroup || selectedGroup === 'none' ? null : selectedGroup };
      const response = await fetchData(url, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'access-token': config.userData.bo_access_token,
        },
        body: JSON.stringify(bidData),
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.detail || data.message || 'Failed to update group');
      }

      toast({
        title: t('myBids.groupUpdateSuccess'),
        description: selectedGroup === 'none'
          ? t('myBids.groupRemoved')
          : t('myBids.groupAssigned', { group: selectedGroup.toUpperCase() }),
        status: 'success',
        duration: 9000,
        isClosable: true,
      });

      setIsEditing(false);
      onGroupUpdate(bid.id, selectedGroup === 'none' ? null : selectedGroup);
    } catch (error) {
      console.error('Error details:', error);
      toast({
        title: t('myBids.error'),
        description: error.message || t('myBids.groupUpdateError'),
        status: 'error',
        duration: 9000,
        isClosable: true,
      });
    }
  };

  const explanationProps = {
    title: t('myBids.orGroupExplanation.title'),
    main: t('myBids.orGroupExplanation.main'),
    example: t('myBids.orGroupExplanation.example'),
  };

  const canEdit = item?.status === 'paused' && !bid?.deleted && bid?.author === config.userData.id;

  if (!bid) return null;

  const groupLabel = (
    <span className="group-chip">
      {t('myBids.groupName', { group: bid?.bids_group_name?.toUpperCase() })}
    </span>
  );

  // ── Empty + can-edit: show "Add to Or Bids Group" chip
  if (!bid.bids_group_name && !isEditing) {
    if (!canEdit) return null;
    return (
      <div className="group-editor">
        <ExplanationTooltip {...explanationProps}>
          <button
            type="button"
            className="group-chip group-chip--action"
            onClick={() => setIsEditing(true)}
          >
            <Combine size={12} aria-hidden="true" />
            <span>{t('myBids.addToGroup')}</span>
          </button>
        </ExplanationTooltip>
      </div>
    );
  }

  // ── Editing: dropdown + gold save + X cancel
  if (isEditing) {
    return (
      <div className="group-editor">
        <div className="group-editor__edit">
          <CircuitDropdown
            variant="compact"
            value={selectedGroup || 'none'}
            onChange={(newGroup) => {
              if (newGroup !== 'none' && hasNonPausedItemsInGroup(newGroup)) {
                toast({
                  title: t('myBids.error'),
                  description: t('myBids.groupHasClosedItems'),
                  status: 'error',
                  duration: 9000,
                  isClosable: true,
                });
                return;
              }
              setSelectedGroup(newGroup);
            }}
            ariaLabel={t('myBids.orGroup', { defaultValue: 'Or Bids Group' })}
            options={groups.map((group) => ({
              value: group,
              label: group === 'none'
                ? t('myBids.noGroup')
                : t('myBids.groupName', { group: group.toUpperCase() }),
            }))}
          />
          <div className="group-editor__actions">
            <button
              type="button"
              className="bid-limit-submit bid-limit-submit--xs"
              onClick={handleSave}
            >
              {t('myBids.save')}
            </button>
            <button
              type="button"
              className="group-editor__cancel"
              onClick={() => setIsEditing(false)}
              aria-label={t('myBids.cancel', { defaultValue: 'Cancel' })}
            >
              <CloseSmall />
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ── Shown with group + maybe edit button
  const altLots = bid.alternative_bids?.length > 0
    ? bid.alternative_bids.map((alt) => alt.lot)
    : null;

  return (
    <div className="group-editor">
      <div className="group-editor__display">
        {altLots ? (
          <AltLotsTooltip
            title={t('myBids.alternativeLotsTitle', { defaultValue: 'Alternative Lots' })}
            lots={altLots}
          >
            <span className="group-chip">
              {t('myBids.groupName', { group: bid?.bids_group_name?.toUpperCase() })}
            </span>
          </AltLotsTooltip>
        ) : groupLabel}
        {canEdit && (
          <ExplanationTooltip {...explanationProps}>
            <button
              type="button"
              className="group-chip group-chip--action"
              onClick={() => setIsEditing(true)}
            >
              <Combine size={12} aria-hidden="true" />
              <span>{t('myBids.edit')}</span>
            </button>
          </ExplanationTooltip>
        )}
      </div>
    </div>
  );
};

export default GroupEditor;
