import React, { useState, useEffect, useContext } from 'react';
import { useToast, Spinner } from '@chakra-ui/react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';

const LaptopIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <rect x="3" y="4" width="18" height="12" rx="2" />
    <line x1="1" y1="20" x2="23" y2="20" />
  </svg>
);

const EnvelopeIcon = () => (
  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
    <rect x="2" y="4" width="20" height="16" rx="2" />
    <polyline points="2 7 12 13 22 7" />
  </svg>
);

const MyMaxBidLimit = ({ accessToken, saleUuid, userUuid }) => {
  // TODO(circuit): replace Chakra useToast with a native skill toast.
  const toast = useToast();
  const { t } = useTranslation();
  const [allBidderInfo, setAllBidderInfo] = useState(null);
  const [pendingUpdates, setPendingUpdates] = useState({});
  const [isSubmitting, setIsSubmitting] = useState({});
  const config = useContext(ConfigContext);
  // Site-level flag: the personal (max bid) limit is neither shown
  // nor settable on these sites.
  const noPersonalLimit = !!config.siteConfig?.noPersonalLimit;

  useEffect(() => {
    if (noPersonalLimit) return;
    fetchAllCreditInfo();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [accessToken, saleUuid, userUuid, noPersonalLimit]);

  const fetchAllCreditInfo = async () => {
    try {
      const response = await fetch(`${config.backendUrl}/api/v1.0/bidder_ids?user_uuid=${userUuid}&sale_uuid=${saleUuid}`, {
        headers: { 'access-token': accessToken },
      });
      if (!response.ok) return;
      const data = await response.json();
      if (data.count === 0) return;

      const filteredBidders = data.data.filter((bidder) =>
        bidder.bidder_type === 'website' || bidder.bidder_type === 'mail'
      );

      const sortedBidders = filteredBidders.sort((a, b) => {
        if (a.bidder_type === 'website' && b.bidder_type !== 'website') return -1;
        if (a.bidder_type !== 'website' && b.bidder_type === 'website') return 1;
        return parseInt(a.bidder_number) - parseInt(b.bidder_number);
      });

      setAllBidderInfo(sortedBidders);
      setPendingUpdates({});
    } catch (error) {
      toast({
        title: t('myCredit.error'),
        description: error.title,
        status: 'error',
        duration: 9000,
        isClosable: true,
      });
    }
  };

  const handleMaxBidUpdate = async (bidderId, newMaxBid) => {
    if (noPersonalLimit) return;
    setIsSubmitting((prev) => ({ ...prev, [bidderId]: true }));
    try {
      const response = await fetch(`${config.backendUrl}/api/v1.0/bidder_ids/${bidderId}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'access-token': accessToken,
        },
        body: JSON.stringify({
          max_bid: newMaxBid,
        }),
      });

      if (!response.ok) throw new Error('Failed to update max bid');

      await fetchAllCreditInfo();
      toast({
        title: t('myCredit.maxBidUpdated'),
        status: 'success',
        duration: 3000,
      });
    } catch (error) {
      toast({
        title: t('myCredit.error'),
        description: error.message,
        status: 'error',
        duration: 3000,
      });
    } finally {
      setIsSubmitting((prev) => ({ ...prev, [bidderId]: false }));
    }
  };

  if (noPersonalLimit) return null;
  if (!allBidderInfo) return null;

  return (
    <div className="bid-limits">
      <h3 className="bid-limits__section-title">{t('myCredit.maxBidLimits')}</h3>
      <p className="bid-limits__help">{t('myCredit.maxBidLimitsHelp')}</p>

      <div className="bid-limits__list">
        {allBidderInfo.map((bidder) => {
              const storedValue = String(bidder.max_bid) === '-1' ? '' : bidder.max_bid;
              const pendingValue = pendingUpdates[bidder.id];
              const currentValue = pendingValue !== undefined ? pendingValue : storedValue;
              const isDirty = pendingValue !== undefined && pendingValue !== storedValue;
              const submitting = !!isSubmitting[bidder.id];

              return (
                <div key={bidder.id} className="bid-limit-row">
                  <div className="bid-limit-row__bidder">
                    {bidder.bidder_type === 'website' ? <LaptopIcon /> : <EnvelopeIcon />}
                    <span>
                      {t('myCredit.bidderNumber', { number: bidder.bidder_number })}{' '}
                      <span className="bid-limit-row__type">({bidder.bidder_type})</span>
                    </span>
                  </div>

                  <span className="bid-limit-row__label">{t('myCredit.currentLimit')}</span>

                  <input
                    type="number"
                    className="field-input bid-limit-row__input"
                    value={currentValue}
                    placeholder={t('myCredit.unlimited')}
                    onChange={(e) => setPendingUpdates((prev) => ({
                      ...prev,
                      [bidder.id]: e.target.value,
                    }))}
                  />

              <button
                type="button"
                className="bid-limit-submit"
                disabled={!isDirty || submitting}
                onClick={() => handleMaxBidUpdate(bidder.id, pendingUpdates[bidder.id] || '-1')}
              >
                {submitting ? <Spinner size="sm" /> : t('myCredit.setBiddingLimit')}
              </button>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default MyMaxBidLimit;
