// Card validation and utility functions are now imported from PaymentUtils

const validateExpiryDate = (month, year) => {
  const currentDate = new Date();
  const currentYear = currentDate.getFullYear();
  const currentMonth = currentDate.getMonth() + 1; // JavaScript months are 0-based

  const expYear = parseInt(year);
  const expMonth = parseInt(month);

  if (expYear < currentYear) {
    return false;
  }
  if (expYear === currentYear && expMonth < currentMonth) {
    return false;
  }
  return true;
};

const validateForm = (formData, cardType) => {
  const errors = [];

  // Validate cardholder name
  if (!formData.cardholderName.trim()) {
    errors.push('Cardholder name is required');
  } else if (formData.cardholderName.trim().length < 2) {
    errors.push('Cardholder name must be at least 2 characters long');
  }

  // Validate card number
  const cleanCardNumber = formData.cardNumber.replace(/\s/g, '');
  if (!cleanCardNumber) {
    errors.push('Card number is required');
  } else if (cleanCardNumber.length < 13) {
    errors.push('Card number must be at least 13 digits');
  } else if (!cardType) {
    errors.push('Card type not recognized. Please check your card number');
  } else if (!validateCardNumber(cleanCardNumber, cardType)) {
    errors.push('Invalid card number. Please check the digits and try again');
  }

  // Validate expiry date
  if (!formData.expiryMonth) {
    errors.push('Expiry month is required');
  } else if (!formData.expiryYear) {
    errors.push('Expiry year is required');
  } else if (!validateExpiryDate(formData.expiryMonth, formData.expiryYear)) {
    errors.push('Card has expired or expiry date is invalid');
  }

  // Validate CVV
  if (!formData.cvv) {
    errors.push('CVV is required');
  } else {
    const cvvLength = cardType === 'amex' ? 4 : 3;
    if (formData.cvv.length !== cvvLength) {
      errors.push(`CVV must be ${cvvLength} digits for ${cardType === 'amex' ? 'American Express' : 'this card type'}`);
    }
  }

  return { isValid: errors.length === 0, errors };
};

const CardTypeIndicator = ({ type }) => {
  if (!type || !CARD_TYPES[type]) return null;
  
  return (
    <HStack spacing={2} alignItems="center">
      <Image
        src={CARD_TYPES[type].logo}
        alt={type}
        height="24px"
        objectFit="contain"
        loading="lazy"
      />
    </HStack>
  );
};

const PaymentMethods = ({ savedCards = [], setSavedCards, onPaymentMethodsChange }) => {
  const { t, i18n } = useTranslation();
  const config = useContext(ConfigContext);
  const toast = useToast();
  const [showAddForm, setShowAddForm] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [formData, setFormData] = useState({
    cardholderName: '',
    cardNumber: '',
    expiryMonth: '',
    expiryYear: '',
    cvv: '',
    isDefault: false
  });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [cardType, setCardType] = useState('');
  const [, setDefaultCardId] = useState(null);
  const [selectedAddress, setSelectedAddress] = useState(null);
  const [savedAddresses, setSavedAddresses] = useState([]);
  const [showNewAddressForm, setShowNewAddressForm] = useState(false);
  const [countryNames, setCountryNames] = useState({});
  const [editingCard, setEditingCard] = useState(null);
  const { isOpen: isDeleteOpen, onOpen: onDeleteOpen, onClose: onDeleteClose } = useDisclosure();
  const [cardToDelete, setCardToDelete] = useState(null);
  const [acceptJsLoaded, setAcceptJsLoaded] = useState(false);
  
  // Save new address using common utility
  const handleSaveNewAddress = async (addressFormData) => {
    try {
      // Use common save address utility
      const savedAddress = await handleSaveAddress({
        config,
        addressFormData,
        addressId: null // null for new addresses
      });

      // Transform saved address to component format
      const transformedAddress = transformAddressForComponent(savedAddress);

      // Add to saved addresses
      setSavedAddresses(prev => [...prev, transformedAddress]);
      
      // Select the new address
      setSelectedAddress(transformedAddress);
      setShowNewAddressForm(false);

      toast({
        title: 'Address saved successfully',
        status: 'success',
        duration: 3000,
      });

      return transformedAddress;

    } catch (error) {
      console.error('Error saving address:', error);
      setError(error.message || 'Failed to save address');
      throw error;
    }
  };

  // Load Accept.js script using shared utility
  useEffect(() => {
    const loadScript = async () => {
      try {
        // Check if already loaded
        if (isAcceptJsLoaded()) {
          setAcceptJsLoaded(true);
          return;
        }

        // Load using shared utility
        await loadAcceptJs(config);
        setAcceptJsLoaded(true);
      } catch (error) {
        console.error('Failed to load Accept.js:', error);
        setError('Failed to load payment processor. Please refresh the page.');
      }
    };

    loadScript();
  }, [config]);

  // Set up default card and loading state based on props
  useEffect(() => {
    setIsLoading(false);
    
    // Set default card if exists
    const defaultCard = savedCards.find(card => card.isDefault);
    if (defaultCard) {
      setDefaultCardId(defaultCard.id);
    }
    
    // Don't automatically select the first address
    setSelectedAddress(null);
  }, [savedCards]);

  useEffect(() => {
    const loadCountryNames = async () => {
      try {
        const formatter = new AddressFormatter(i18n.language);
        const countries = await formatter.getCountries();
        const namesMap = countries.reduce((map, country) => {
          map[country.code] = country.name;
          return map;
        }, {});
        setCountryNames(namesMap);
      } catch (error) {
        console.error('Error loading country names:', error);
      }
    };
    loadCountryNames();
  }, [i18n.language]);

  // Separate effect to fetch addresses using common utility
  useEffect(() => {
    const fetchUserAddresses = async () => {
      try {
        if (!config.userData || !config.userData.uuid || !config.userData.bo_access_token) {
          // Wait until user data is fully loaded
          return;
        }

        // Use common fetch addresses utility
        const addresses = await fetchAddresses({ config });
        
        // Transform addresses to component format
        const transformedAddresses = addresses.map(transformAddressForComponent);
        
        setSavedAddresses(transformedAddresses);

        // Automatically select the default address if one exists
        const defaultAddress = transformedAddresses.find(addr => addr.is_default);
        if (defaultAddress) {
          setSelectedAddress(prev => prev || defaultAddress);
        }
        
      } catch (err) {
        console.error('Error fetching addresses:', err);
        // Fall back to empty addresses on error, don't show error to user for addresses
        setSavedAddresses([]);
      }
    };

    fetchUserAddresses();
  }, [config]);

  const handleSetDefaultCard = async (cardId) => {
    try {
      setIsSubmitting(true);
      
      // Update via API first
      await updatePaymentMethod({ 
        config, 
        paymentMethodId: cardId,
        updates: { is_default: true, client_uuid: config.userData.uuid }
      });
      
      // Update local state
      const updatedCards = savedCards.map(card => ({
        ...card,
        isDefault: card.id === cardId
      }));
      setSavedCards(updatedCards);
      setDefaultCardId(cardId);
      
      // Refresh payment methods in parent component
      if (onPaymentMethodsChange) {
        await onPaymentMethodsChange();
      }
      
      toast({
        title: t('payment.defaultCardUpdated') || 'Default card updated',
        status: 'success',
        duration: 3000,
      });
    } catch (err) {
      console.error('Error updating default card:', err);
      setError(err.message || t('payment.updateDefaultError') || 'Failed to update default card');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    
    if (name === 'cardNumber') {
      const formatted = formatCardNumber(value);
      setFormData(prev => ({
        ...prev,
        [name]: formatted
      }));
      setCardType(detectCardType(formatted));
      return;
    }

    if (name === 'expiryMonth' && value.length === 2) {
      document.getElementsByName('expiryYear')[0]?.focus();
    }

    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const handleCardNumberChange = (e) => {
    const formatted = formatCardNumber(e.target.value);
    setFormData(prev => ({ ...prev, cardNumber: formatted }));
    setCardType(detectCardType(formatted));
  };

  const handleDeleteCard = async (cardId) => {
    try {
      setIsSubmitting(true);
      
      // Use real API to delete the card
      await deletePaymentMethod({ config, paymentMethodId: cardId });
      
      setSavedCards(cards => cards.filter(card => card.id !== cardId));
      
      // If deleted card was default, set another as default
      const remainingCards = savedCards.filter(card => card.id !== cardId);
      const deletedCard = savedCards.find(card => card.id === cardId);
      
      if (deletedCard?.isDefault && remainingCards.length > 0) {
        const newDefaultCard = remainingCards[0];
        // Update the new default card via API
        await updatePaymentMethod({ 
          config, 
          paymentMethodId: newDefaultCard.id,
          updates: { is_default: true, client_uuid: config.userData.uuid }
        });
        
        setSavedCards(cards => 
          cards.map(card => 
            card.id === newDefaultCard.id 
              ? { ...card, isDefault: true }
              : card
          )
        );
        setDefaultCardId(newDefaultCard.id);
      }
      
      // Refresh payment methods in parent component
      if (onPaymentMethodsChange) {
        await onPaymentMethodsChange();
      }
      
      toast({
        title: t('payment.cardDeleted') || 'Card deleted successfully',
        status: 'success',
        duration: 3000,
      });
      
      onDeleteClose();
      
    } catch (err) {
      console.error('Error deleting card:', err);
      setError(err.message || t('payment.deleteError') || 'Failed to delete card');
    } finally {
      setIsSubmitting(false);
    }
  };

  const confirmDeleteCard = (card) => {
    setCardToDelete(card);
    onDeleteOpen();
  };

  const handleEditCard = (card) => {
    setEditingCard(card);
    setFormData({
      cardholderName: card.cardholderName,
      cardNumber: `**** **** **** ${card.last4}`,
      expiryMonth: card.expiryMonth,
      expiryYear: card.expiryYear,
      cvv: '',
      isDefault: card.isDefault
    });
    setCardType(card.cardType);
    setShowAddForm(true);
  };

  const resetForm = () => {
    setFormData({
      cardholderName: '',
      cardNumber: '',
      expiryMonth: '',
      expiryYear: '',
      cvv: '',
      isDefault: false
    });
    setCardType('');
    setError('');
    setSuccess('');
    setEditingCard(null);
  };

  const cancelEdit = () => {
    setShowAddForm(false);
    resetForm();
  };

  const handleAcceptJsResponse = async (response) => {
    if (response.messages.resultCode === 'Error') {
      // Go over messages array and display all errors.
      const errorMessages = response.messages.message.map(msg => msg.text).join('. ');
      setError(errorMessages);
      setIsSubmitting(false);
      return;
    }

    try {

      // Prepare card data for saving
      const cardData = {
        dataValue: response.opaqueData.dataValue,
        dataDescriptor: response.opaqueData.dataDescriptor,
        cardNumber: formData.cardNumber.replace(/\s/g, ''),
        cardholderName: formData.cardholderName,
        expiryMonth: formData.expiryMonth,
        expiryYear: formData.expiryYear
      };

      const billingAddress = selectedAddress ? {
        first_name: selectedAddress.address.first_name,
        last_name: selectedAddress.address.last_name,
        thoroughfare: selectedAddress.address.thoroughfare,
        premise: selectedAddress.address.premise,
        locality: selectedAddress.address.locality,
        administrative_area: selectedAddress.address.administrative_area,
        postal_code: selectedAddress.address.postal_code,
        country: selectedAddress.address.country
      } : null;

      // Save via real API
      const savedPaymentMethod = await savePaymentMethod({
        config,
        cardData,
        billingAddress,
        isDefault: formData.isDefault
      });

      // Transform to component format
      const transformedCard = transformPaymentMethodForComponent(savedPaymentMethod);

      let updatedCards;
      if (editingCard) {
        updatedCards = savedCards.map(card => 
          card.id === editingCard.id ? transformedCard : card
        );
        setSuccess(t('payment.cardUpdated') || 'Card updated successfully!');
      } else {
        updatedCards = [...savedCards, transformedCard];
        setSuccess(t('payment.cardSaved') || 'Card added successfully!');
      }

      // If this card is set as default, remove default from others
      if (transformedCard.isDefault) {
        updatedCards = updatedCards.map(card => 
          card.id === transformedCard.id ? card : { ...card, isDefault: false }
        );
        setDefaultCardId(transformedCard.id);
      }

      setSavedCards(updatedCards);
      
      // Refresh payment methods in parent component
      if (onPaymentMethodsChange) {
        await onPaymentMethodsChange();
      }
      
      setIsSubmitting(false);
      setShowAddForm(false);
      resetForm();
      
      toast({
        title: editingCard ? t('payment.cardUpdated') : t('payment.cardSaved'),
        status: 'success',
        duration: 3000,
      });

    } catch (error) {
      console.error('Error saving payment method:', error);
      setError(error.message || 'Failed to save payment method');
      setIsSubmitting(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    const validation = validateForm(formData, cardType);
    if (!validation.isValid) {
      setError(validation.errors.join('. '));
      return;
    }

    if (!selectedAddress && !editingCard && !showNewAddressForm) {
      setError(t('payment.addressRequired') || 'Please select a billing address');
      return;
    }

    setIsSubmitting(true);
    
    try {
      // Check if Accept.js is loaded and available
      if (!acceptJsLoaded) {
        throw new Error('Payment processor is still loading. Please wait a moment and try again.');
      }
      
      if (typeof window.Accept === 'undefined') {
        throw new Error('Payment processor not available. Please refresh the page and try again.');
      }
      
      if (typeof window.Accept.dispatchData !== 'function') {
        throw new Error('Payment processor not properly initialized. Please refresh the page.');
      }

      // For demo purposes, if Accept.js credentials are not configured, simulate the process
      const hasValidCredentials = config.siteConfig.authorizeNetClientKey &&
                                 config.siteConfig.authorizeNetApiLoginId &&
                                 config.siteConfig.authorizeNetClientKey !== 'YOUR_PUBLIC_CLIENT_KEY';

      if (!hasValidCredentials) {
        console.warn('Accept.js credentials not configured, simulating card save for demo');
        // Simulate successful tokenization for demo
        setTimeout(() => {
          handleAcceptJsResponse({
            messages: { resultCode: 'Ok' },
            opaqueData: { 
              dataValue: 'demo_payment_nonce_' + Date.now(),
              dataDescriptor: 'COMMON.ACCEPT.INAPP.PAYMENT'
            }
          });
        }, 1000);
        return;
      }

      // Prepare data for Accept.js
      const authData = {
        clientKey: config.siteConfig.authorizeNetClientKey,
        apiLoginID: config.siteConfig.authorizeNetApiLoginId
      };

      const cardData = {
        cardNumber: formData.cardNumber.replace(/\s/g, ''),
        month: formData.expiryMonth.padStart(2, '0'),
        year: formData.expiryYear,
        cardCode: formData.cvv,
        fullName: formData.cardholderName,
      };

      // Wrap Accept.js call in try-catch to handle internal errors
      try {
        var secureData = {};
        secureData.authData = authData;
        secureData.cardData = cardData;
        // If using banking information instead of card information,
        // send the bankData object instead of the cardData object.
        //
        // secureData.bankData = bankData;

        window.Accept.dispatchData(secureData, handleAcceptJsResponse);
        // Call Accept.js
        // window.Accept.dispatchData(authData, cardData, handleAcceptJsResponse);
      } catch (acceptError) {
        console.error('Accept.js internal error:', acceptError);
        // If Accept.js fails, fall back to demo mode for now
        console.warn('Accept.js failed, using demo fallback');
        setTimeout(() => {
          handleAcceptJsResponse({
            messages: { resultCode: 'Ok' },
            opaqueData: { 
              dataValue: 'fallback_payment_nonce_' + Date.now(),
              dataDescriptor: 'COMMON.ACCEPT.INAPP.PAYMENT'
            }
          });
        }, 1000);
      }
      
    } catch (err) {
      console.error('Payment error:', err);
      setError(err.message || t('payment.saveFailed') || 'Failed to process payment. Please try again.');
      setIsSubmitting(false);
    }
  };

  if (isLoading) {
    return (
      <div className="billing-page--loading">
        <Spinner color="blue.500" size="xl" thickness="4px" />
      </div>
    );
  }

  const openAddForm = () => {
    setShowAddForm(true);
    const defaultAddress = savedAddresses.find((addr) => addr.is_default);
    if (defaultAddress && !selectedAddress) {
      setSelectedAddress(defaultAddress);
    }
    setShowNewAddressForm(false);
  };

  return (
    <div className="payment-methods">
      <div className="payment-methods__head">
        <p className="payment-methods__intro">
          {t('payment.intro', { defaultValue: 'Manage the cards you use to pay for invoices. Set a default and update billing details below.' })}
        </p>
        {!showAddForm && (
          <button
            type="button"
            className="btn-primary-action"
            onClick={openAddForm}
          >
            <Plus size={14} /> {t('payment.addNew')}
          </button>
        )}
      </div>

      {savedCards.length === 0 ? (
        <div className="payment-methods__empty">
          <CreditCard size={36} aria-hidden="true" />
          <p className="payment-methods__empty-title">
            {t('payment.noCards') || 'No saved payment methods'}
          </p>
          <p className="payment-methods__empty-hint">
            {t('payment.addFirstCard') || 'Add your first payment method to get started'}
          </p>
        </div>
      ) : (
          <div className="payment-card-list">
            {savedCards.map((card) => {
              const ownerName = `${card.billingAddress?.firstName || ''} ${card.billingAddress?.lastName || ''}`.trim();
              const cityStateZip = [
                card.billingAddress?.city,
                card.billingAddress?.state ? `, ${card.billingAddress.state}` : '',
                card.billingAddress?.zip ? ` ${card.billingAddress.zip}` : '',
              ].join('');

              return (
                <article
                  key={card.id}
                  className={`payment-card${card.isDefault ? ' is-default' : ''}`}
                >
                  <header className="payment-card__head">
                    <CardTypeIndicator type={card.cardType} />
                    <div className="payment-card__title-block">
                      <p className="payment-card__title">
                        <span className="payment-card__brand">
                          {card.cardType.charAt(0).toUpperCase() + card.cardType.slice(1)}
                        </span>
                        <span className="payment-card__dots">•••• {card.last4}</span>
                      </p>
                      {card.isDefault && (
                        <span className="payment-card__default-pill">
                          {t('payment.default', { defaultValue: 'Default' })}
                        </span>
                      )}
                    </div>
                  </header>

                  {card.billingAddress && (ownerName || card.billingAddress.address || cityStateZip) && (
                    <address className="payment-card__address">
                      {ownerName && <span>{ownerName}</span>}
                      {card.billingAddress.address && <span>{card.billingAddress.address}</span>}
                      {cityStateZip.trim() && <span>{cityStateZip.trim()}</span>}
                    </address>
                  )}

                  <div className="payment-card__actions">
                    {!card.isDefault && (
                      <button
                        type="button"
                        className="btn-secondary-action btn-secondary-action--gold"
                        onClick={() => handleSetDefaultCard(card.id)}
                      >
                        {t('payment.setAsDefaultBtn', { defaultValue: 'Set as Default' })}
                      </button>
                    )}
                    <button
                      type="button"
                      className="payment-card__icon-btn"
                      onClick={() => handleEditCard(card)}
                      aria-label={t('payment.editCard')}
                    >
                      <Edit size={14} aria-hidden="true" />
                    </button>
                    <button
                      type="button"
                      className="payment-card__icon-btn payment-card__icon-btn--danger"
                      onClick={() => confirmDeleteCard(card)}
                      aria-label={t('payment.deleteCard')}
                    >
                      <Trash2 size={14} aria-hidden="true" />
                    </button>
                  </div>
                </article>
              );
            })}
          </div>
        )}

        {/* Add New Card Form */}
        {showAddForm && (
          <Card className="payment-form-card">
            <CardHeader>
              <div className="payment-form-card__head">
                <div className="payment-form-card__title">
                  <CreditCard size={20} aria-hidden="true" />
                  <span>{editingCard ? t('payment.editCard') : t('payment.addNew')}</span>
                </div>
                <button
                  type="button"
                  className="payment-form-card__close"
                  onClick={cancelEdit}
                  aria-label={t('payment.close', { defaultValue: 'Close' })}
                >
                  <X size={14} aria-hidden="true" />
                </button>
              </div>
            </CardHeader>
            <CardBody px={{ base: 4, md: 6 }}>
              {/* Address Section */}
              <Box mb={6}>
                <Text fontSize="lg" mb={4}>{t('payment.billingInformation')}</Text>
                
                {/* Debug Info */}
                {process.env.NODE_ENV === 'development' && (
                  <Box p={2} bg="gray.100" borderRadius="md" mb={4} fontSize="xs">
                    <Text><strong>Debug:</strong></Text>
                    <Text>showNewAddressForm: {showNewAddressForm.toString()}</Text>
                    <Text>selectedAddress: {selectedAddress?.id || 'none'}</Text>
                    <Text>savedAddresses count: {savedAddresses.length}</Text>
                  </Box>
                )}

                <RadioGroup onChange={(value) => {
                  const selected = savedAddresses.find(addr => (addr.id || '').toString() === value);
                  setSelectedAddress(selected);
                  setShowNewAddressForm(false);
                }} value={showNewAddressForm ? '' : (selectedAddress?.id || '').toString()}>
                  <Stack spacing={3}>
                    {/* Existing Addresses */}
                    {savedAddresses.map((addr) => {
                      // Handle both old mock format and new API format
                      const address = addr.address || addr;
                      const firstName = (address.first_name || '').toString();
                      const lastName = (address.last_name || '').toString();
                      const street = (address.thoroughfare || address.premise || address.address || '').toString();
                      const city = (address.locality || address.city || '').toString();
                      const state = (address.administrative_area || address.state || '').toString();
                      const zip = (address.postal_code || address.zip || '').toString();
                      const countryCode = (address.country || '').toString();
                      const countryName = countryNames[countryCode] || countryCode;

                      return (
                        <Card key={addr.id}>
                          <CardBody>
                            <Radio value={(addr.id || '').toString()}>
                              <Box>
                                <Flex alignItems="center" gap={2}>
                                  <Text fontWeight="medium">
                                    {firstName} {lastName}
                                  </Text>
                                  {addr.is_default && (
                                    <Badge colorScheme="green" size="sm">
                                      Default
                                    </Badge>
                                  )}
                                </Flex>
                                <Text color="gray.600" fontSize="sm">
                                  {street}
                                </Text>
                                <Text color="gray.600" fontSize="sm">
                                  {city}, {state} {zip}{countryName ? `, ${countryName}` : ''}
                                </Text>
                              </Box>
                            </Radio>
                          </CardBody>
                        </Card>
                      );
                    })}
                  </Stack>
                </RadioGroup>

                {/* Add-new-address toggle — checkbox so the user can
                    turn it back off without picking another option. */}
                <label className="checkbox-row payment-address__new">
                  <input
                    type="checkbox"
                    checked={showNewAddressForm}
                    onChange={(e) => {
                      if (e.target.checked) {
                        setSelectedAddress(null);
                        setShowNewAddressForm(true);
                      } else {
                        setShowNewAddressForm(false);
                      }
                    }}
                  />
                  <span className="checkbox-label">{t('payment.addNewAddress')}</span>
                </label>

                {/* New Address Form */}
                {showNewAddressForm && (
                  <Box mt={4}>
                    <PaymentAddressSection
                      savedAddresses={savedAddresses}
                      onAddressSelect={async (addressFormData) => {
                        try {
                          // Save the address using the same logic as MyAccount.js
                          await handleSaveNewAddress(addressFormData);
                        } catch (error) {
                          console.error('Failed to save address:', error);
                          // Error is already handled in handleSaveNewAddress
                        }
                      }}
                      namePrefixes={DEFAULT_NAME_PREFIXES}
                      defaultCountry="US"
                      showFormInitially={true}  
                    />
                  </Box>
                )}
              </Box>

              {/* Card Information Form */}
              <form onSubmit={handleSubmit} noValidate>
                {error && (
                  <Alert status="error" mb={4}>
                    <AlertIcon as={AlertCircle} />
                    <AlertDescription>{error}</AlertDescription>
                  </Alert>
                )}
                
                {success && (
                  <Alert status="success" mb={4}>
                    <AlertIcon />
                    <AlertDescription>{success}</AlertDescription>
                  </Alert>
                )}
                
                <SupportedCards />
                <FormControl mb={4}>
                  <FormLabel>{t('payment.cardholderName')}</FormLabel>
                  <Input
                    name="cardholderName"
                    value={formData.cardholderName}
                    onChange={handleInputChange}
                    placeholder={t('payment.cardholderNamePlaceholder')}
                    required
                    width="100%"
                    maxWidth="100%"
                    boxSizing="border-box"
                  />
                </FormControl>

                <FormControl mb={4}>
                  <FormLabel>{t('payment.cardNumber')}</FormLabel>
                  <CardNumberInput 
                    value={formData.cardNumber}
                    onChange={handleCardNumberChange}
                    cardType={cardType}
                  />
                </FormControl>

                <div className="payment-form__triple">
                  <FormControl>
                    <FormLabel>{t('payment.month')}</FormLabel>
                    <Select
                      name="expiryMonth"
                      value={formData.expiryMonth}
                      onChange={handleInputChange}
                      placeholder="MM"
                      required
                    >
                      {Array.from({ length: 12 }, (_, i) => i + 1).map(month => (
                        <option key={month} value={month.toString().padStart(2, '0')}>
                          {month.toString().padStart(2, '0')}
                        </option>
                      ))}
                    </Select>
                  </FormControl>

                  <FormControl>
                    <FormLabel>{t('payment.year')}</FormLabel>
                    <Select
                      name="expiryYear"
                      value={formData.expiryYear}
                      onChange={handleInputChange}
                      placeholder="YYYY"
                      required
                    >
                      {Array.from({ length: 10 }, (_, i) => new Date().getFullYear() + i).map(year => (
                        <option key={year} value={year.toString()}>
                          {year}
                        </option>
                      ))}
                    </Select>
                  </FormControl>

                  <FormControl>
                    <FormLabel>
                      {t('payment.cvv')}
                      <Tooltip
                        label={cardType === 'amex' ? t('payment.cvvAmex') : t('payment.cvvOther')}
                        placement="top"
                      >
                        <InfoIcon ml={2} color="gray.500" />
                      </Tooltip>
                    </FormLabel>
                    <Input
                      name="cvv"
                      value={formData.cvv}
                      onChange={handleInputChange}
                      type="password"
                      placeholder={cardType === 'amex' ? '4 digits' : '3 digits'}
                      maxLength={cardType === 'amex' ? 4 : 3}
                      required
                    />
                  </FormControl>
                </div>

                {/* Set-as-default toggle (or first-card info notice) */}
                {savedCards.length === 0 ? (
                  <p className="payment-form__notice">
                    <InfoIcon aria-hidden="true" />
                    <span>
                      {t('payment.firstCardDefault', { defaultValue: 'This will be your default payment method.' })}
                    </span>
                  </p>
                ) : (
                  <label className="checkbox-row payment-form__default">
                    <input
                      type="checkbox"
                      name="isDefault"
                      checked={formData.isDefault}
                      onChange={handleInputChange}
                    />
                    <span className="checkbox-label">
                      {t('payment.setAsDefault', { defaultValue: 'Set as default payment method' })}
                    </span>
                  </label>
                )}

                <div className="payment-form__actions">
                  <button
                    type="submit"
                    className="bid-limit-submit"
                    disabled={isSubmitting}
                  >
                    <Save size={14} />
                    {isSubmitting
                      ? t('payment.saving', { defaultValue: 'Saving…' })
                      : editingCard
                        ? t('payment.updateCard')
                        : t('payment.saveMethod')}
                  </button>
                  <button
                    type="button"
                    className="btn-secondary-action"
                    onClick={cancelEdit}
                  >
                    {t('payment.cancel')}
                  </button>
                </div>
              </form>
            </CardBody>
          </Card>
        )}

      {/* Delete Confirmation Modal — TODO(circuit): native popover. */}
      <Modal isOpen={isDeleteOpen} onClose={onDeleteClose}>
        <ModalOverlay />
        <ModalContent>
          <ModalHeader>Delete Payment Method</ModalHeader>
          <ModalCloseButton />
          <ModalBody>
            <Text>
              Are you sure you want to delete this payment method?
            </Text>
            {cardToDelete && (
              <Box mt={4} p={4} bg="gray.50" borderRadius="md">
                <Flex alignItems="center" gap={3}>
                  <CardTypeIndicator type={cardToDelete.cardType} />
                  <Box>
                    <Text fontWeight="medium">
                      {cardToDelete.cardType.charAt(0).toUpperCase() + cardToDelete.cardType.slice(1)} •••• {cardToDelete.last4}
                    </Text>
                    <Text fontSize="sm" color="gray.600">
                      {cardToDelete.cardholderName}
                    </Text>
                  </Box>
                </Flex>
              </Box>
            )}
          </ModalBody>
          <ModalFooter>
            <Button variant="ghost" mr={3} onClick={onDeleteClose}>
              Cancel
            </Button>
            <Button
              colorScheme="red"
              onClick={() => handleDeleteCard(cardToDelete?.id)}
              isLoading={isSubmitting}
            >
              Delete
            </Button>
          </ModalFooter>
        </ModalContent>
      </Modal>
    </div>
  );
};

export default PaymentMethods;