import fetchData from './Util';

/**
 * Fetch customer payment methods from the backend
 * @param {Object} params - Parameters object
 * @param {Object} params.config - Config context with userData and siteData
 * @param {number|null} params.clientId - Client ID (optional, will be fetched if not provided)
 * @returns {Promise<Array>} - Array of payment methods
 */
export const fetchPaymentMethods = async ({ config, clientId = null }) => {
  try {
    if (!config.userData || !config.userData.uuid || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    // Fetch payment methods from backend
    const response = await fetchData(
      `${config.siteData.backoffice_url_lang}/api/payment-methods?client_uuid=${config.userData.uuid}`,
      {
        mockData: 'payment-methods',
        headers: { 'access-token': config.userData.bo_access_token },
      }
    );
    
    if (!response.ok) {
      throw new Error('Failed to fetch payment methods');
    }
    
    const result = await response.json();
    return result.data || [];

  } catch (error) {
    console.error('Error fetching payment methods:', error);
    throw error;
  }
};

/**
 * Save a new payment method (with Accept.js tokenization)
 * @param {Object} params - Parameters object
 * @param {Object} params.config - Config context with userData and siteData
 * @param {Object} params.cardData - Card data from Accept.js
 * @param {Object} params.billingAddress - Billing address information
 * @param {boolean} params.isDefault - Whether this should be the default payment method
 * @param {number|null} params.clientId - Client ID (optional, will be fetched if not provided)
 * @returns {Promise<Object>} - Saved payment method data
 */
export const savePaymentMethod = async ({
  config,
  cardData,
  billingAddress,
  isDefault = false,
  clientId = null
}) => {
  try {
    if (!config.userData || !config.userData.uuid || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    // Check existing payment methods to determine if this should be default
    let shouldBeDefault = isDefault;
    try {
      const existingPaymentMethods = await fetchPaymentMethods({ config, clientId });
      if (existingPaymentMethods.length === 0) {
        // If no existing payment methods, automatically set as default
        shouldBeDefault = true;
        console.log('No existing payment methods found, setting as default');
      }
    } catch (error) {
      console.warn('Could not fetch existing payment methods, proceeding with original isDefault value:', error);
    }

    // Prepare payment method data for backend
    const paymentMethodData = {
      client_uuid: config.userData.uuid,
      is_default: shouldBeDefault,
      payment_nonce: cardData.dataValue,
      payment_descriptor: cardData.dataDescriptor,
      card_type: detectCardType(cardData.cardNumber || ''),
      last_four: (cardData.cardNumber || '').slice(-4),
      cardholder_name: cardData.cardholderName || '',
      expiry_month: cardData.expiryMonth || '',
      expiry_year: cardData.expiryYear || '',
      billing_address: billingAddress ? {
        first_name: billingAddress.first_name || '',
        last_name: billingAddress.last_name || '',
        address: billingAddress.thoroughfare || '',
        address2: billingAddress.premise || '',
        city: billingAddress.locality || '',
        state: billingAddress.administrative_area || '',
        zip: billingAddress.postal_code || '',
        country: billingAddress.country || 'US'
      } : null
    };

    console.log('Saving payment method:', paymentMethodData);

    // POST to backend API
    const response = await fetchData(
      `${config.siteData.backoffice_url_lang}/api/payment-methods`,
      {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'access-token': config.userData.bo_access_token,
        },
        body: JSON.stringify(paymentMethodData),
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.title || 'Failed to save payment method');
    }

    const responseData = await response.json();
    const savedPaymentMethod = responseData.data;

    // Augment the response with original card data for the UI
    savedPaymentMethod.originalCardData = {
      cardType: paymentMethodData.card_type,
      last4: paymentMethodData.last_four,
      cardholderName: paymentMethodData.cardholder_name,
      expiryMonth: paymentMethodData.expiry_month,
      expiryYear: paymentMethodData.expiry_year,
      isDefault: paymentMethodData.is_default,
      billingAddress: billingAddress
    };

    console.log('Payment method saved successfully:', savedPaymentMethod);
    return savedPaymentMethod;

  } catch (error) {
    console.error('Error saving payment method:', error);
    throw error;
  }
};

/**
 * Delete a payment method
 * @param {Object} params - Parameters object
 * @param {Object} params.config - Config context with userData and siteData
 * @param {string} params.paymentMethodId - Payment method ID to delete
 * @returns {Promise<void>}
 */
export const deletePaymentMethod = async ({ config, paymentMethodId }) => {
  try {
    if (!config.userData || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }
    const paymentMethodData = {
      client_uuid: config.userData.uuid
    };

    const response = await fetchData(
      `${config.siteData.backoffice_url_lang}/api/payment-methods/${paymentMethodId}`,
      {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
          'access-token': config.userData.bo_access_token,
        },
        body: JSON.stringify(paymentMethodData),
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.title || 'Failed to delete payment method');
    }

    console.log('Payment method deleted successfully');

  } catch (error) {
    console.error('Error deleting payment method:', error);
    throw error;
  }
};

/**
 * Update payment method (e.g., set as default)
 * @param {Object} params - Parameters object
 * @param {Object} params.config - Config context with userData and siteData
 * @param {string} params.paymentMethodId - Payment method ID to update
 * @param {Object} params.updates - Updates to apply
 * @returns {Promise<Object>} - Updated payment method data
 */
export const updatePaymentMethod = async ({ config, paymentMethodId, updates }) => {
  try {
    if (!config.userData || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    const response = await fetchData(
      `${config.siteData.backoffice_url_lang}/api/payment-methods/${paymentMethodId}`,
      {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'access-token': config.userData.bo_access_token,
        },
        body: JSON.stringify(updates),
      }
    );

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.title || 'Failed to update payment method');
    }

    const responseData = await response.json();
    const updatedPaymentMethod = responseData.data[0];

    console.log('Payment method updated successfully:', updatedPaymentMethod);
    return updatedPaymentMethod;

  } catch (error) {
    console.error('Error updating payment method:', error);
    throw error;
  }
};

/**
 * Detect card type from card number
 * @param {string} cardNumber - Card number (can include spaces)
 * @returns {string} - Card type (visa, mastercard, amex, etc.)
 */
export const detectCardType = (cardNumber) => {
  const cleanNumber = cardNumber.replace(/\s/g, '');
  
  const cardTypes = {
    visa: /^4/,
    mastercard: /^5[1-5]/,
    amex: /^3[47]/,
    discover: /^6(?:011|5)/,
    jcb: /^35/,
    dinersclub: /^(30|36|38)/
  };

  for (const [type, pattern] of Object.entries(cardTypes)) {
    if (pattern.test(cleanNumber)) {
      return type;
    }
  }
  
  return 'unknown';
};

/**
 * Transform API payment method data to component format
 * @param {Object} apiPaymentMethod - Payment method from API
 * @returns {Object} - Transformed payment method for component use
 */
export const transformPaymentMethodForComponent = (apiPaymentMethod) => {
  // Handle different response formats based on whether it's from save response or fetch response
  const isFromSaveResponse = apiPaymentMethod.paymentProfileId && apiPaymentMethod.success;
  
  if (isFromSaveResponse && apiPaymentMethod.originalCardData) {
    // This is from the save payment method response with augmented card data
    const cardData = apiPaymentMethod.originalCardData;
    return {
      id: apiPaymentMethod.paymentProfileId || '',
      cardType: cardData.cardType || 'unknown',
      last4: cardData.last4 || '',
      cardholderName: cardData.cardholderName || '',
      expiryMonth: cardData.expiryMonth || '',
      expiryYear: cardData.expiryYear || '',
      isDefault: cardData.isDefault || false,
      billingAddress: cardData.billingAddress ? {
        firstName: cardData.billingAddress.first_name || '',
        lastName: cardData.billingAddress.last_name || '',
        address: cardData.billingAddress.thoroughfare || cardData.billingAddress.address || '',
        city: cardData.billingAddress.locality || cardData.billingAddress.city || '',
        state: cardData.billingAddress.administrative_area || cardData.billingAddress.state || '',
        zip: cardData.billingAddress.postal_code || cardData.billingAddress.zip || '',
        country: cardData.billingAddress.country || 'US'
      } : null,
    };
  } else if (isFromSaveResponse) {
    // Fallback for save response without augmented data
    return {
      id: apiPaymentMethod.paymentProfileId || '',
      cardType: 'visa', // Default to visa for now, can be enhanced later
      last4: '1111', // Default for demo, can be enhanced later
      cardholderName: 'Alex Smith', // Default for demo, can be enhanced later
      isDefault: false, // Default for demo, can be enhanced later
      billingAddress: null, // Can be enhanced later if needed
    };
  } else {
    // This is from the fetch payment methods response (existing logic)
    return {
      id: apiPaymentMethod.paymentProfileId || '',
      cardType: apiPaymentMethod.cardType || 'unknown',
      // Extract 4 digits from card number for display.
      last4: apiPaymentMethod.cardNumber ? (apiPaymentMethod.cardNumber.match(/[A-Z]{3}(\d{4})/i) || [])[1] || '' : '',
      cardholderName: apiPaymentMethod.cardholderName || '',
      isDefault: apiPaymentMethod.is_default || false,
      billingAddress: apiPaymentMethod.billTo ? {
        firstName: apiPaymentMethod.billTo.firstName || '',
        lastName: apiPaymentMethod.billTo.lastName || '',
        address: typeof apiPaymentMethod.billTo.address === 'object' 
          ? (apiPaymentMethod.billTo.address?.thoroughfare || apiPaymentMethod.billTo.address?.premise || '') 
          : (apiPaymentMethod.billTo.address || ''),
        city: typeof apiPaymentMethod.billTo.city === 'object'
          ? (apiPaymentMethod.billTo.city?.locality || '')
          : (apiPaymentMethod.billTo.city || ''),
        state: typeof apiPaymentMethod.billTo.state === 'object'
          ? (apiPaymentMethod.billTo.state?.administrative_area || '')
          : (apiPaymentMethod.billTo.state || ''),
        zip: typeof apiPaymentMethod.billTo.zip === 'object'
          ? (apiPaymentMethod.billTo.zip?.postal_code || '')
          : (apiPaymentMethod.billTo.zip || ''),
        country: typeof apiPaymentMethod.billTo.country === 'object'
          ? (apiPaymentMethod.billTo.country?.country || 'US')
          : (apiPaymentMethod.billTo.country || 'US')
      } : null,
    };
  }
};

/**
 * Validate card number using Luhn algorithm
 * @param {string} cardNumber - Card number to validate
 * @param {string} cardType - Expected card type
 * @returns {boolean} - Whether the card number is valid
 */
export const validateCardNumber = (cardNumber, cardType) => {
  const cleanNumber = cardNumber.replace(/\s/g, '');
  
  // Check valid lengths for each card type
  const validLengths = {
    visa: [16],
    mastercard: [16],
    amex: [15],
    discover: [16],
    jcb: [16],
    dinersclub: [14]
  };
  
  // Check if length is valid for card type
  const isValidLength = cardType && validLengths[cardType]?.includes(cleanNumber.length);
  if (!isValidLength) {
    return false;
  }

  // Perform Luhn algorithm check
  const digits = cleanNumber.split('').map(Number);
  const checkDigit = digits.pop();
  const sum = digits
    .reverse()
    .map((digit, index) => {
      if (index % 2 === 0) {
        const doubled = digit * 2;
        return doubled > 9 ? doubled - 9 : doubled;
      }
      return digit;
    })
    .reduce((acc, curr) => acc + curr, 0);
  
  return (sum + checkDigit) % 10 === 0;
};

/**
 * Format card number with spaces every 4 digits
 * @param {string} value - Raw card number
 * @returns {string} - Formatted card number
 */
export const formatCardNumber = (value) => {
  const v = value.replace(/\s+/g, '').replace(/[^0-9]/gi, '');
  const matches = v.match(/\d{4,16}/g);
  const match = (matches && matches[0]) || '';
  const parts = [];
  for (let i = 0, len = match.length; i < len; i += 4) {
    parts.push(match.substring(i, i + 4));
  }
  if (parts.length) {
    return parts.join(' ');
  } else {
    return v;
  }
};