import fetchData from './Util';

/**
 * Common address saving function used by both MyAccount.js and PaymentMethods.js
 * @param {Object} params - Parameters object
 * @param {Object} params.config - Config context with userData and siteData
 * @param {Object} params.addressFormData - Form data from AddressForm component
 * @param {number|null} params.addressId - Existing address ID for updates (null for new addresses)
 * @param {number|null} params.clientId - Client ID (optional, will be fetched if not provided)
 * @returns {Promise<Object>} - Saved address data
 */
export const handleSaveAddress = async ({
  config,
  addressFormData,
  addressId = null,
  clientId = null
}) => {
  try {
    // Validate required config
    if (!config.userData || !config.userData.uuid || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    // Get client ID if not provided
    let resolvedClientId = clientId;
    if (!resolvedClientId) {
      const userResponse = await fetchData(
        `${config.siteData.backoffice_url_lang}/api/v1.0/datatable-clients?filter[uuid][value]=${config.userData.uuid}`,
        {
          mockData: 'api-me',
          headers: { 'access-token': config.userData.bo_access_token },
        }
      );
      
      if (userResponse.ok) {
        const userResult = await userResponse.json();
        const userData = userResult.data[0];
        resolvedClientId = userData?.id;
      }

      if (!resolvedClientId) {
        throw new Error('Unable to get client ID');
      }
    }

    // Prepare address data using the standard API structure
    const addressData = {
      client: resolvedClientId,
      default_address: addressFormData.defaultAddress || false,
      address_types: addressFormData.addressTypes || ['billing'],
      address: {
        name_prefix: Number(addressFormData.namePrefix) || 0,
        care_of: addressFormData.careOf || '',
        first_name: addressFormData.firstName || '',
        last_name: addressFormData.lastName || '',
        organisation_name: addressFormData.company || '',
        thoroughfare: addressFormData.address1 || '',
        premise: addressFormData.address2 || '',
        locality: addressFormData.city || '',
        administrative_area: addressFormData.province || '',
        postal_code: addressFormData.zip || '',
        country: addressFormData.country || 'US',
      },
    };


    // Determine if this is an update or create
    const isUpdate = !!addressId;
    const url = `${config.siteData.backoffice_url_lang}/api/client-address${isUpdate ? `/${addressId}` : ''}`;

    const response = await fetchData(url, {
      method: isUpdate ? 'PATCH' : 'POST',
      headers: {
        'Content-Type': 'application/json',
        'access-token': config.userData.bo_access_token,
      },
      body: JSON.stringify(addressData),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.title || 'Failed to save address');
    }

    const responseData = await response.json();
    const savedAddress = responseData.data[0];

    return savedAddress;

  } catch (error) {
    console.error('Error saving address:', error);
    throw error;
  }
};

/**
 * Delete an address (sets published: 0)
 * @param {Object} params - Parameters object
 * @param {Object} params.config - Config context with userData and siteData
 * @param {number} params.addressId - Address ID to delete
 * @returns {Promise<void>}
 */
export const handleDeleteAddress = async ({ config, addressId }) => {
  try {
    if (!config.userData || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    const url = `${config.siteData.backoffice_url_lang}/api/client-address/${addressId}`;

    const response = await fetchData(url, {
      method: 'PATCH',
      headers: {
        'Content-Type': 'text/plain;charset=UTF-8',
        'access-token': config.userData.bo_access_token,
      },
      body: JSON.stringify({ published: 0 }),
    });

    if (!response.ok) {
      throw new Error('Network response was not ok');
    }
  } catch (error) {
    console.error('Error deleting address:', error);
    throw error;
  }
};

/**
 * Fetch addresses for a client
 * @param {Object} params - Parameters object
 * @param {Object} params.config - Config context with userData and siteData
 * @param {number|null} params.clientId - Client ID (optional, will be fetched if not provided)
 * @returns {Promise<Array>} - Array of addresses
 */
export const fetchAddresses = async ({ config, clientId = null }) => {
  try {
    if (!config.userData || !config.userData.uuid || !config.userData.bo_access_token) {
      throw new Error('User authentication required');
    }

    // Get client ID if not provided
    let resolvedClientId = clientId;
    if (!resolvedClientId) {
      const userResponse = await fetchData(
        `${config.siteData.backoffice_url_lang}/api/v1.0/datatable-clients?filter[uuid][value]=${config.userData.uuid}`,
        {
          mockData: 'api-me',
          headers: { 'access-token': config.userData.bo_access_token },
        }
      );
      
      if (userResponse.ok) {
        const userResult = await userResponse.json();
        const userData = userResult.data[0];
        resolvedClientId = userData?.id;
      }

      if (!resolvedClientId) {
        throw new Error('Unable to get client ID');
      }
    }

    // Fetch addresses
    const addressResponse = await fetchData(
      `${config.siteData.backoffice_url_lang}/api/client-address?filter[client]=${resolvedClientId}`,
      {
        mockData: 'api-client-address',
        headers: { 'access-token': config.userData.bo_access_token },
      }
    );
    
    if (!addressResponse.ok) {
      throw new Error('Failed to fetch addresses');
    }
    
    const addressResult = await addressResponse.json();
    return addressResult.data;

  } catch (error) {
    console.error('Error fetching addresses:', error);
    throw error;
  }
};

/**
 * Transform API address data to component format
 * @param {Object} apiAddress - Address from API
 * @returns {Object} - Transformed address for component use
 */
export const transformAddressForComponent = (apiAddress) => {
  const addressData = apiAddress.address || apiAddress;
  
  return {
    id: `address-${apiAddress.id}`,
    apiId: apiAddress.id,
    address: {
      first_name: addressData.first_name || apiAddress.first_name || '',
      last_name: addressData.last_name || apiAddress.last_name || '',
      thoroughfare: addressData.thoroughfare || '',
      premise: addressData.premise || '',
      locality: addressData.locality || addressData.city || apiAddress.city || '',
      administrative_area: addressData.administrative_area || addressData.state || apiAddress.state || '',
      postal_code: addressData.postal_code || addressData.zip || apiAddress.zip || '',
      country: addressData.country || apiAddress.country || 'US'
    },
    is_default: apiAddress.default_address || false,
  };
};