import React, { useState, useEffect, useContext } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
// Chakra still in use: the confirm-purchase modal shell + Spinner.
import {
  Spinner,
  Modal, ModalOverlay, ModalContent, ModalBody,
  useDisclosure,
} from '@chakra-ui/react';
import fetchData from '../utils/Util';

const SubscriptionPurchase = () => {
  const { t } = useTranslation();
  const config = useContext(ConfigContext);
  const [isLoading, setIsLoading] = useState(true);
  const [isProcessing, setIsProcessing] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState(null);
  const [subscriptionPlans, setSubscriptionPlans] = useState([]);
  const [error, setError] = useState('');
  const { isOpen, onOpen, onClose } = useDisclosure();


  // Fetch subscription plans

  // Fetch data on component mount
  useEffect(() => {
    // Get sale_id for subscription plans - from backoffice_subscription_magazines_sale_nid variable
    const fetchMagazineSaleId = async () => {
      if (!config.siteData || !config.siteData.backoffice_url) {
        throw new Error('No backoffice URL available');
      }

      const response = await fetchData(
        `${config.siteData.backoffice_url_lang}/api/v1.0/invoke-function-public/variable_get?params[0]=backoffice_subscription_magazines_sale_nid`
      );

      if (!response.ok) {
        throw new Error('Failed to fetch subscription sale ID');
      }

      const result = await response.json();
      if (!result[0]) {
        throw new Error('No subscription sale ID returned');
      }

      return result[0];
    };

    const fetchSubscriptionPlans = async (saleId) => {
      try {
        if (!config.siteData || !config) {
          return;
        }

        const response = await fetchData(
          `${config.siteData.backoffice_url_lang}/api/v1.0/items-public?filter[item_status]=ready&fields=nid,label,description,opening_price&sale_id=${saleId}`
        );

        if (!response.ok) {
          throw new Error(response.title || t('subscriptionPurchase.networkError'));
        }

        const result = await response.json();

        // Item.description can arrive as a plain string, `{ en: '...' }`,
        // `{ rendered: '...' }`, or `{ en: { rendered: '...' } }` — coerce
        // to a string so dangerouslySetInnerHTML doesn't render
        // `[object Object]`.
        const getDescriptionHtml = (desc) => {
          if (!desc) return '';
          if (typeof desc === 'string') return desc;
          if (typeof desc === 'object') {
            if (typeof desc.rendered === 'string') return desc.rendered;
            if (desc.en) {
              if (typeof desc.en === 'string') return desc.en;
              if (typeof desc.en?.rendered === 'string') return desc.en.rendered;
            }
          }
          return '';
        };
        const getLabel = (label, fallback) => {
          if (!label) return fallback;
          if (typeof label === 'string') return label;
          if (typeof label?.en === 'string') return label.en;
          if (typeof label?.rendered === 'string') return label.rendered;
          return fallback;
        };

        // Transform API data to our plan format and sort by opening_price
        const transformedPlans = result.data
          .map((item, index) => ({
            id: item.id || index,
            nid: item.nid,
            name: getLabel(item.label, `Plan ${index + 1}`),
            price: item.opening_price?.raw || parseFloat(item.opening_price) || 0,
            description: getDescriptionHtml(item.description),
            priceValue: item.opening_price?.raw || parseFloat(item.opening_price) || 0,
          }))
          .sort((a, b) => a.priceValue - b.priceValue);

        setSubscriptionPlans(transformedPlans);

      } catch (error) {
        setError(error.message);
        console.error('Error fetching subscription plans:', error);
      }
    };

    const fetchDataAsync = async () => {
      try {
        const saleId = await fetchMagazineSaleId();
        await fetchSubscriptionPlans(saleId);
      } catch (error) {
        setError(error.message);
      } finally {
        setIsLoading(false);
      }
    };

    fetchDataAsync().catch((error) => {
      setError(error.message);
      setIsLoading(false);
    });
  }, [config, t]);

  const handlePurchase = (plan) => {
    setSelectedPlan(plan);
    onOpen();
  };

  const handleConfirmPurchase = async () => {
    if (!selectedPlan) return;

    setIsProcessing(true);

    try {
      // Send POST request to buy-subscirption endpoint
      const response = await fetchData(
        `${config.siteData.backoffice_url_lang}/api/v1.0/buy-subscirption/${selectedPlan.nid}`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          }
        }
      );

      if (!response.ok) {
        throw new Error(response.title || t('subscriptionPurchase.purchaseError'));
      }

      // Close modal and redirect to billing page
      onClose();
      window.location.href = '/billing';

    } catch (error) {
      console.error('Purchase error:', error);
      setError(error.message || t('subscriptionPurchase.purchaseError'));
      onClose();
    } finally {
      setIsProcessing(false);
    }
  };

  const handleCancelPurchase = () => {
    setSelectedPlan(null);
    onClose();
  };

  if (isLoading || !config.siteData) {
    return (
      <div className="subscription-page subscription-page--loading">
        <Spinner color="blue.500" size="xl" thickness="4px" />
      </div>
    );
  }

  if (config.success === false) {
    return (
      <div className="subscription-page">
        <div className="cream-note cream-note--error" role="alert">
          {t('subscriptionPurchase.cannotAccessSiteSettings')}
        </div>
      </div>
    );
  }

  const isLoggedIn = config.userData && config.userData.bo_access_token;

  if (!isLoggedIn) {
    return (
      <div className="subscription-page">
        <section className="rc-card account-card subscription-purchase">
          <header className="card-head">
            <h2 className="page-title">{t('subscriptionPurchase.title')}</h2>
          </header>
          <div className="card-body subscription-purchase__login">
            <div className="cream-note cream-note--warning" role="status">
              {t('subscriptionPurchase.loginRequired')}
            </div>
            <button
              type="button"
              className="bid-limit-submit"
              onClick={() => { window.location.href = '/login'; }}
            >
              {t('subscriptionPurchase.goToLogin')}
            </button>
          </div>
        </section>
      </div>
    );
  }

  return (
    <div className="subscription-page">
      <section className="rc-card account-card subscription-purchase">
        <header className="card-head">
          <h2 className="page-title">{t('subscriptionPurchase.title')}</h2>
        </header>

        <div className="card-body">
          <p className="subscription-purchase__subtitle">
            {t('subscriptionPurchase.subtitle')}
          </p>

          {error && (
            <div className="cream-note cream-note--error" role="alert">
              <strong>{t('subscriptionPurchase.error')}</strong>{error}
            </div>
          )}

          <div className="plan-grid">
            {subscriptionPlans.map((plan) => (
              <article key={plan.id} className="plan-card">
                <header className="plan-card__head">
                  <h3 className="plan-card__name">{plan.name}</h3>
                  <p className="plan-card__price">
                    <span className="plan-card__currency">$</span>
                    <span className="plan-card__amount">{plan.price}</span>
                  </p>
                </header>

                <div
                  className="plan-card__description"
                  dangerouslySetInnerHTML={{ __html: plan.description }}
                />

                <button
                  type="button"
                  className="bid-limit-submit plan-card__cta"
                  disabled={isProcessing}
                  onClick={() => handlePurchase(plan)}
                >
                  {t('subscriptionPurchase.choosePlan')} →
                </button>
              </article>
            ))}
          </div>

          <div className="subscription-purchase__footnote">
            <p>{t('subscriptionPurchase.securePayment')}</p>
            <p className="subscription-purchase__cancel-anytime">
              {t('subscriptionPurchase.cancelAnytime')}
            </p>
          </div>
        </div>
      </section>

      {/* Confirmation popover — Chakra Modal is a transparent shell;
          the actual card is built inside .circuit-user-ui with design
          tokens (matches the Compare modal pattern). */}
      <Modal isOpen={isOpen} onClose={handleCancelPurchase} isCentered>
        <ModalOverlay bg="rgba(28, 22, 14, 0.55)" backdropFilter="blur(4px)" />
        <ModalContent
          maxW="480px"
          bg="transparent"
          boxShadow="none"
          className="subscription-confirm-modal"
        >
          <ModalBody p={0}>
            <div className="circuit-user-ui">
              <div className="confirm-modal">
                <header className="confirm-modal__head">
                  <h2 className="confirm-modal__title">
                    {t('subscriptionPurchase.confirmPurchase', { defaultValue: 'Confirm Purchase' })}
                  </h2>
                  <button
                    type="button"
                    className="confirm-modal__close"
                    onClick={handleCancelPurchase}
                    disabled={isProcessing}
                    aria-label={t('subscriptionPurchase.close', { defaultValue: 'Close' })}
                  >
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                      <line x1="18" y1="6" x2="6" y2="18" />
                      <line x1="6" y1="6" x2="18" y2="18" />
                    </svg>
                  </button>
                </header>

                <div className="confirm-modal__body">
                  {selectedPlan && (
                    <>
                      <p className="confirm-modal__message">
                        {t('subscriptionPurchase.confirmMessage', { defaultValue: 'Are you sure you want to purchase this subscription plan?' })}
                      </p>
                      <div className="confirm-modal__summary">
                        <div className="confirm-modal__summary-row">
                          <span className="confirm-modal__summary-label">
                            {t('subscriptionPurchase.plan', { defaultValue: 'Plan' })}
                          </span>
                          <span className="confirm-modal__summary-value">
                            {selectedPlan.name}
                          </span>
                        </div>
                        <div className="confirm-modal__summary-row">
                          <span className="confirm-modal__summary-label">
                            {t('subscriptionPurchase.total', { defaultValue: 'Total' })}
                          </span>
                          <span className="confirm-modal__summary-value confirm-modal__summary-value--price">
                            ${selectedPlan.price}
                          </span>
                        </div>
                      </div>
                    </>
                  )}
                </div>

                <footer className="confirm-modal__footer">
                  <button
                    type="button"
                    className="btn-secondary-action"
                    onClick={handleCancelPurchase}
                    disabled={isProcessing}
                  >
                    {t('subscriptionPurchase.cancel', { defaultValue: 'Cancel' })}
                  </button>
                  <button
                    type="button"
                    className="bid-limit-submit confirm-modal__confirm"
                    onClick={handleConfirmPurchase}
                    disabled={isProcessing}
                  >
                    {isProcessing
                      ? t('subscriptionPurchase.processing', { defaultValue: 'Processing…' })
                      : t('subscriptionPurchase.approve', { defaultValue: 'Approve & Continue' })}
                  </button>
                </footer>
              </div>
            </div>
          </ModalBody>
        </ModalContent>
      </Modal>
    </div>
  );
};

export default SubscriptionPurchase;