import React, { useContext, useState } from 'react';
import ReCAPTCHA from 'react-google-recaptcha';
import fetchData from '../utils/Util';
import { ConfigContext } from '../config/Config';
import { useTranslation } from 'react-i18next';

const ForgotPassword = () => {
  const { t, i18n } = useTranslation();
  const config = useContext(ConfigContext);
  const [email, setEmail] = useState('');
  const [captchaValue, setCaptchaValue] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    try {
      if (!captchaValue) {
        setError(t('forgotPassword.captchaError'));
        return;
      }

      const response = await fetchData(
        `${config.backendUrl}/api/user_password`,
        {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            language: i18n.language === 'zh' ? 'zh-hans' : i18n.language,
            mail: email,
            site: config.siteName,
          }),
        }
      );

      if (response.ok) {
        setSuccess(t('forgotPassword.successMessage'));
      } else {
        const errorData = await response.json();
        setError(errorData.title || t('forgotPassword.errorMessage'));
      }
    } catch (err) {
      setError(t('forgotPassword.generalError'));
    }
  };

  return (
    <div className="auth-page forgot-password">
      <section className="rc-card auth-card">
        <header className="card-head">
          <h2 className="page-title">{t('forgotPassword.title')}</h2>
        </header>

        <div className="card-body">
          <div className="auth-intro">
            <p>{t('forgotPassword.instruction1')}</p>
            <p>{t('forgotPassword.instruction2')}</p>
          </div>

          {error && (
            <div className="cream-note cream-note--error" role="alert">
              {error}
            </div>
          )}

          {success && (
            <div className="cream-note cream-note--success" role="status">
              {success}
            </div>
          )}

          <form onSubmit={handleSubmit} className="acct-form">
            <div className="field">
              <label htmlFor="fp-email" className="field-label">
                {t('forgotPassword.emailLabel')}<span className="req">*</span>
              </label>
              <input
                id="fp-email"
                type="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                placeholder={t('forgotPassword.emailPlaceholder')}
                required
                autoComplete="email"
                className="field-input"
              />
            </div>

            {/* TODO(circuit): the ReCAPTCHA iframe is third-party and won't
                respect design tokens. Wrapper provides spacing only. */}
            <div className="recaptcha-wrap">
              <ReCAPTCHA
                sitekey={config.recaptchaKey}
                hl={i18n.language}
                onChange={(token) => setCaptchaValue(token)}
              />
            </div>

            <p
              className="required-note"
              dangerouslySetInnerHTML={{
                __html: t('register.requiredFields', { asterisk: '<span class="req">*</span>' }),
              }}
            />

            <div className="card-actions">
              <button type="submit" className="btn-primary-action">
                {t('forgotPassword.submitButton')}
              </button>
            </div>
          </form>
        </div>
      </section>
    </div>
  );
};

export default ForgotPassword;
