import React, { useState, useEffect, useContext } from 'react';
import { createPortal } from 'react-dom';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import { useDataCache } from '../services/DataCache';
import { isCacheResetRequested } from '../utils/resetParam';
import { Spinner } from '@chakra-ui/react';

const SaleInfo = ({ saleNid }) => {
    const { t, i18n } = useTranslation();
    const config = useContext(ConfigContext);
    const { fetchSaleInfo } = useDataCache();
    const [saleData, setSaleData] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState(null);


    // About-this-sale modal state
    const [isAboutOpen, setIsAboutOpen] = useState(false);

    // Lock page scroll while modal is open; close on Esc.
    useEffect(() => {
        if (!isAboutOpen) return undefined;
        const prevOverflow = document.body.style.overflow;
        document.body.style.overflow = 'hidden';
        const onKey = (e) => { if (e.key === 'Escape') setIsAboutOpen(false); };
        window.addEventListener('keydown', onKey);
        return () => {
            document.body.style.overflow = prevOverflow;
            window.removeEventListener('keydown', onKey);
        };
    }, [isAboutOpen]);

    useEffect(() => {
        const loadSaleInfo = async () => {
            if (!saleNid || !config.siteData) return;

            setIsLoading(true);
            setError(null);

            try {
                // Fetch sale info using DataCache. `?reset=1` on the host
                // page bypasses the client cache and travels to the API.
                const data = await fetchSaleInfo(saleNid, config.siteData.backoffice_url_lang, {
                    reset: isCacheResetRequested(),
                });
                setSaleData(data);
            } catch (err) {
                setError(err.message);
            } finally {
                setIsLoading(false);
            }
        };

        loadSaleInfo();
    }, [saleNid, config.siteData, fetchSaleInfo]);

    if (isLoading) {
        return (
            <div className="sale-info-wrapper sale-info-wrapper--loading">
                <Spinner size="lg" />
            </div>
        );
    }

    if (error) {
        return (
            <div className="cream-note cream-note--error sale-info-wrapper__error" role="alert">
                {error}
            </div>
        );
    }

    if (!saleData?.sale) return null;

    // Get current language data, fallback to 'en' if not available
    const currentLang = i18n.language === 'zh' ? 'zh-hans' : i18n.language;
    const languageData = saleData.sale[currentLang] || saleData.sale.en;

    // Get sessions array - convert object to array and sort by parent/date
    const sessionsArray = saleData.sessions ? Object.values(saleData.sessions) : [];

    // Separate parent sessions and child sessions
    const parentSessions = sessionsArray.filter(session => !session.parent);
    const childSessions = sessionsArray.filter(session => session.parent);

    return (
        <div className="sale-info-wrapper">
            {/* Title row — title on the left, About-this-sale trigger on the right. */}
            <div className="sale-info__title-row">
                <h1 className="sale-info__title" dangerouslySetInnerHTML={{ __html: languageData.title }} />
                {(languageData.body || saleData.sale.date_location) && (
                    <button
                        type="button"
                        className="sale-info__about-trigger"
                        onClick={() => setIsAboutOpen(true)}
                    >
                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                            <circle cx="12" cy="12" r="10" />
                            <line x1="12" y1="8" x2="12" y2="12" />
                            <line x1="12" y1="16" x2="12.01" y2="16" />
                        </svg>
                        {t('sale.aboutThisSale', 'About This Sale')}
                    </button>
                )}
            </div>

            {/* Sale Subtitle */}
            {languageData.subtitle && (
                <h2 className="sale-info__subtitle" dangerouslySetInnerHTML={{ __html: languageData.subtitle }} />
            )}

            {/* Sale Date and Location */}
            {saleData.sale.date_location && (
                <p className="sale-info__meta" dangerouslySetInnerHTML={{ __html: saleData.sale.date_location }} />
            )}

            {/* About-this-sale modal */}
            {isAboutOpen && createPortal(
                <div className="circuit-user-ui">
                    <div
                        className="sale-about-modal__overlay"
                        onClick={() => setIsAboutOpen(false)}
                        aria-hidden="true"
                    />
                    <div className="sale-about-modal" role="dialog" aria-modal="true" aria-label={t('sale.aboutThisSale', 'About This Sale')}>
                        <header className="sale-about-modal__head">
                            <h2 className="sale-about-modal__title">
                                {t('sale.aboutThisSale', 'About This Sale')}
                            </h2>
                            <button
                                type="button"
                                className="sale-about-modal__close"
                                onClick={() => setIsAboutOpen(false)}
                                aria-label={t('sale.close', { defaultValue: 'Close' })}
                            >
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                                    <line x1="18" y1="6" x2="6" y2="18" />
                                    <line x1="6" y1="6" x2="18" y2="18" />
                                </svg>
                            </button>
                        </header>

                        <div className="sale-about-modal__body">
                            {/* Sale name (re-printed at top for context) */}
                            <p className="sale-about-modal__sale-name" dangerouslySetInnerHTML={{ __html: languageData.title }} />

                            {/* Sale dates / location */}
                            {saleData.sale.date_location && (
                                <div className="sale-about-modal__dates">
                                    <span className="sale-about-modal__dates-label">
                                        {t('sale.dateAndLocation', { defaultValue: 'Date & Location' })}
                                    </span>
                                    <div className="sale-about-modal__dates-value" dangerouslySetInnerHTML={{ __html: saleData.sale.date_location }} />
                                </div>
                            )}

                            {/* Body content */}
                            {languageData.body && (
                                <div className="sale-about-modal__description" dangerouslySetInnerHTML={{ __html: languageData.body }} />
                            )}
                        </div>
                    </div>
                </div>,
                document.body
            )}

            {/* Table of Contents — compact 3-column table (name, date,
                lot range). Sub-sessions render as indented rows under
                their parent. Body is scrollable when there are many. */}
            {parentSessions.length > 0 && (() => {
                const buildLotRangeUrl = (from, to) => {
                    const url = new URL(saleData.sale.url);
                    url.searchParams.set('lotNumberRange', `${from}-${to}`);
                    return `${url.pathname}${url.search}`;
                };

                const formatSessionDate = (session) => {
                    if (session.date_override) return session.date_override;
                    if (session.date_value && session.date_value !== '1') {
                        const date = new Date(parseInt(session.date_value, 10) * 1000);
                        return date.toLocaleDateString(i18n.language, {
                            month: 'short',
                            day: 'numeric',
                            year: 'numeric',
                        });
                    }
                    return null;
                };

                return (
                    <details className="sale-info__toc" aria-label={t('sale.tableOfContents', 'Table of Contents')}>
                        <summary className="sale-info__toc-head">
                            <span className="sale-info__toc-label">
                                {t('sale.tableOfContents', 'Table of Contents')}
                            </span>
                            <span className="sale-info__toc-count">
                                {parentSessions.length + childSessions.length}{' '}
                                {t('sale.sessions', { defaultValue: 'sessions' })}
                            </span>
                            <span className="sale-info__toc-chevron" aria-hidden="true">
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                    <polyline points="6 9 12 15 18 9" />
                                </svg>
                            </span>
                        </summary>
                        <div className="sale-info__toc-list">
                            {parentSessions.flatMap((session) => {
                                const sessionDate = formatSessionDate(session);
                                const children = childSessions.filter((c) => c.parent === session.id);

                                const parentRow = (
                                    <a
                                        key={session.id}
                                        href={buildLotRangeUrl(session.from_lot, session.to_lot)}
                                        className="sale-info__toc-row"
                                    >
                                        <span className="sale-info__toc-row-name">{session.name}</span>
                                        <span className="sale-info__toc-row-date">{sessionDate || ''}</span>
                                        <span className="sale-info__toc-row-range">
                                            {session.from_lot}–{session.to_lot}
                                        </span>
                                    </a>
                                );

                                const childRows = children.map((child) => (
                                    <a
                                        key={child.id}
                                        href={buildLotRangeUrl(child.from_lot, child.to_lot)}
                                        className="sale-info__toc-row sale-info__toc-row--child"
                                    >
                                        <span className="sale-info__toc-row-name">
                                            <span className="sale-info__toc-row-indent" aria-hidden="true">└─</span>
                                            {child.name}
                                        </span>
                                        <span className="sale-info__toc-row-date" />
                                        <span className="sale-info__toc-row-range">
                                            {child.from_lot}–{child.to_lot}
                                        </span>
                                    </a>
                                ));

                                return [parentRow, ...childRows];
                            })}
                        </div>
                    </details>
                );
            })()}
        </div>
    );
};

export default SaleInfo;
