import React, { useState, useEffect, useContext } from 'react';
import { useTranslation } from 'react-i18next';
import { ConfigContext } from '../config/Config';
import { Spinner } from '@chakra-ui/react';
import fetchData from '../utils/Util';

const Balance = () => {
  const { t } = useTranslation();
  const config = useContext(ConfigContext);
  const [boUserData, setBoUserData] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchBoUserData = async () => {
      try {
        if (config.userData && config.userData.uuid && config.userData.bo_access_token) {
          const response = await fetchData(
            `${config.siteData.backoffice_url_lang}/api/v1.0/datatable-clients?filter[uuid][value]=${config.userData.uuid}`,
            {
              mockData: 'api-me',
              headers: { 'access-token': config.userData.bo_access_token },
            }
          );

          if (!response.ok) {
            throw new Error(response.title || t('balance.networkError'));
          }

          const result = await response.json();
          const data = result.data[0];
          setBoUserData(data);
        }
      } catch (err) {
        setError(err.message);
      } finally {
        setIsLoading(false);
      }
    };

    if (config.siteData) {
      fetchBoUserData().catch((err) => {
        setError(err.message);
        setIsLoading(false);
      });
    }
  }, [config, t]);

  const isLoggedIn = () => {
    return config.userData && config.userData.bo_access_token;
  };

  const getBalanceInfo = () => {
    if (!boUserData || !boUserData.customer_available_balance) {
      return { amount: 0, formatted: '$0.00', hasBalance: false };
    }

    const balance = boUserData.customer_available_balance;
    const rawAmount = balance.raw || 0;
    const formattedAmount = balance.formatted || '$0.00';
    const hasBalance = rawAmount < 0; // Negative balance means money owed

    return {
      amount: rawAmount,
      formatted: formattedAmount,
      hasBalance,
    };
  };

  const handleBillingRedirect = () => {
    window.location.href = '/billing';
  };

  const handleLoginRedirect = () => {
    window.location.href = `/login?redirect=${encodeURIComponent(window.location.href)}`;
  };

  // Inline wallet icon used as the button's leading visual.
  const WalletIcon = () => (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <path d="M21 12V7H5a2 2 0 0 1 0-4h14v4" />
      <path d="M3 5v14a2 2 0 0 0 2 2h16v-5" />
      <path d="M18 12a2 2 0 0 0 0 4h4v-4Z" />
    </svg>
  );

  const ChevronIcon = () => (
    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <polyline points="9 18 15 12 9 6" />
    </svg>
  );

  // Loading state
  if (isLoading && isLoggedIn()) {
    return (
      <button type="button" className="balance-btn balance-btn--loading" disabled>
        <span className="balance-btn__icon"><WalletIcon /></span>
        <span className="balance-btn__content">
          <span className="balance-btn__caption">{t('balance.balance', { defaultValue: 'Balance' })}</span>
          <span className="balance-btn__value">
            <Spinner size="xs" mr={2} />
            {t('balance.loading')}
          </span>
        </span>
      </button>
    );
  }

  // Error state
  if (error && isLoggedIn()) {
    return (
      <button
        type="button"
        className="balance-btn balance-btn--error"
        onClick={() => window.location.reload()}
      >
        <span className="balance-btn__icon"><WalletIcon /></span>
        <span className="balance-btn__content">
          <span className="balance-btn__caption">{t('balance.balance', { defaultValue: 'Balance' })}</span>
          <span className="balance-btn__value">{t('balance.error')}</span>
        </span>
      </button>
    );
  }

  // Not logged in
  if (!isLoggedIn()) {
    return (
      <button
        type="button"
        className="balance-btn balance-btn--neutral"
        onClick={handleLoginRedirect}
      >
        <span className="balance-btn__icon"><WalletIcon /></span>
        <span className="balance-btn__content">
          <span className="balance-btn__caption">{t('balance.balance', { defaultValue: 'Balance' })}</span>
          <span className="balance-btn__value">{t('balance.loginToSeeBalance')}</span>
        </span>
        <span className="balance-btn__chevron"><ChevronIcon /></span>
      </button>
    );
  }

  const balanceInfo = getBalanceInfo();

  // Outstanding balance — money owed
  if (balanceInfo.hasBalance) {
    return (
      <button
        type="button"
        className="balance-btn balance-btn--owed"
        onClick={handleBillingRedirect}
      >
        <span className="balance-btn__icon"><WalletIcon /></span>
        <span className="balance-btn__content">
          <span className="balance-btn__caption">{t('balance.dueNow', { defaultValue: 'Due Now' })}</span>
          <span className="balance-btn__value">{balanceInfo.formatted}</span>
        </span>
        <span className="balance-btn__chevron"><ChevronIcon /></span>
      </button>
    );
  }

  // No balance — link to billing for invoice history
  return (
    <button
      type="button"
      className="balance-btn balance-btn--clear"
      onClick={handleBillingRedirect}
    >
      <span className="balance-btn__icon"><WalletIcon /></span>
      <span className="balance-btn__content">
        <span className="balance-btn__caption">{t('balance.balance', { defaultValue: 'Balance' })}</span>
        <span className="balance-btn__value">{t('balance.allClear', { defaultValue: 'All Clear' })}</span>
      </span>
      <span className="balance-btn__chevron"><ChevronIcon /></span>
    </button>
  );
};

export default Balance;
