import React from 'react';

const SubscriptionSection = ({ boUserData, t }) => {
  const shouldShowSubscription = () =>
    boUserData && boUserData.subscription_type !== false;

  const getSubscriptionStatus = () => {
    if (!boUserData?.subscription_type || boUserData.subscription_type === 'none') {
      if (boUserData?.cancellation_date) {
        const expirationDate = new Date(boUserData.cancellation_date);
        if (expirationDate > new Date()) return 'error';
        return 'expired';
      }
      return 'none';
    }
    if (boUserData.cancellation_date) {
      const expirationDate = new Date(boUserData.cancellation_date);
      return expirationDate > new Date() ? 'active' : 'expired';
    }
    return 'active';
  };

  const getSubscriptionStatusText = () => {
    const status = getSubscriptionStatus();
    const subscriptionType = boUserData.subscription_type;
    const expirationDate = boUserData.cancellation_date
      ? new Date(boUserData.cancellation_date).toLocaleDateString('en-US', {
          year: 'numeric',
          month: 'long',
          day: 'numeric',
        })
      : null;

    switch (status) {
      case 'none':
        return t('myAccount.subscription.statusNoSubscription');
      case 'error':
        return t('myAccount.subscription.statusError', { date: expirationDate });
      case 'expired':
        return t('myAccount.subscription.statusExpired', { date: expirationDate });
      case 'active': {
        const typeText = subscriptionType === 'digital'
          ? t('myAccount.subscription.digitalOnly').toLowerCase()
          : t('myAccount.subscription.digitalAndPrint').toLowerCase();
        return expirationDate
          ? t('myAccount.subscription.statusActive', { type: typeText, date: expirationDate })
          : t('myAccount.subscription.statusActiveNoDate', { type: typeText });
      }
      default:
        return t('myAccount.subscription.statusNoSubscription');
    }
  };

  const getSubscriptionAlert = () => {
    const status = getSubscriptionStatus();

    const configByStatus = {
      none: {
        variant: 'warning',
        message: t('myAccount.subscription.noSubscriptionMessage'),
        actionHref: '/subscription-purchase',
        actionLabel: t('myAccount.subscription.purchaseSubscription'),
      },
      error: {
        variant: 'error',
        message: t('myAccount.subscription.errorMessage'),
        actionHref: '/contact',
        actionLabel: t('myAccount.subscription.contactOffice'),
      },
      expired: {
        variant: 'warning',
        message: t('myAccount.subscription.expiredMessage'),
        actionHref: '/subscription-purchase',
        actionLabel: t('myAccount.subscription.renewSubscription'),
      },
      active: {
        variant: 'success',
        message: t('myAccount.subscription.activeMessage'),
        actionHref: '/subscription-magazine',
        actionLabel: t('myAccount.subscription.viewMagazine'),
      },
    };

    const cfg = configByStatus[status];
    if (!cfg) return null;

    return (
      <div className={`cream-note cream-note--${cfg.variant} subscription-section__alert`} role="status">
        <span className="subscription-section__alert-msg">{cfg.message}</span>
        <a
          href={cfg.actionHref}
          className="bid-limit-submit subscription-section__action"
        >
          {cfg.actionLabel}
        </a>
      </div>
    );
  };

  if (!shouldShowSubscription()) return null;

  return (
    <section className="subscription-section">
      <header className="subscription-section__head">
        <h3 className="subscription-section__title">
          {t('myAccount.subscription.title')}
        </h3>
      </header>

      {boUserData && (
        <>
          <p className="subscription-section__status">
            {getSubscriptionStatusText()}
          </p>
          {getSubscriptionAlert()}
        </>
      )}
    </section>
  );
};

export default SubscriptionSection;
