import React from 'react';
import { useTranslation } from 'react-i18next';

const GroupSummary = ({ groupedBids }) => {
  const { t } = useTranslation();

  // Collect each group's lots (including alternative lots).
  const bidGroups = {};
  Object.entries(groupedBids).forEach(([lot, lotData]) => {
    lotData.bids.forEach((bid) => {
      if (bid.bids_group_name) {
        if (!bidGroups[bid.bids_group_name]) {
          bidGroups[bid.bids_group_name] = new Set();
        }
        bidGroups[bid.bids_group_name].add(lot);
        if (bid.alternative_bids) {
          bid.alternative_bids.forEach((altBid) => {
            bidGroups[bid.bids_group_name].add(altBid.lot);
          });
        }
      }
    });
  });

  if (Object.keys(bidGroups).length === 0) return null;

  const sortedGroups = Object.entries(bidGroups).sort(([a], [b]) => a.localeCompare(b));

  return (
    <div className="group-summary">
      <span className="group-summary__label">{t('myBids.bidGroups')}</span>
      <div className="group-summary__chips">
        {sortedGroups.map(([group, lots]) => (
          <span key={group} className="group-summary__chip">
            <span className="group-summary__chip-label">
              {t('myBids.groupName', { group: group.toUpperCase() })}
            </span>
            <span className="group-summary__chip-lots">
              {Array.from(lots).sort((a, b) => Number(a) - Number(b)).join(', ')}
            </span>
          </span>
        ))}
      </div>
    </div>
  );
};

export default GroupSummary;
