/**
 * `?reset=1` (or `?reset=true`) on the HOST page asks the app to bypass its
 * caches and re-fetch from the API, forwarding the parameter so backend/edge
 * caches are skipped too. Shared by the item page and the sale page.
 *
 * IMPORTANT: the flag is captured ONCE at script load. The sale page syncs
 * its filter state into the URL with history.replaceState (dropping foreign
 * query params like reset) before the first fetch runs — reading
 * window.location lazily would therefore miss the parameter. Captured at
 * module evaluation, the flag survives the rewrite and applies to every
 * fetch of this page load; fresh responses overwrite the caches, so the
 * next normal load serves updated data.
 */
const requestedAtLoad =
  typeof window !== 'undefined' &&
  ['1', 'true'].includes(new URLSearchParams(window.location.search).get('reset'));

export function isCacheResetRequested() {
  return requestedAtLoad;
}

export default isCacheResetRequested;
